    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setClearColor(0x000000, 0);

    this.scene = new Scene();
    this.clock = new Clock();

    const fov = 45;
    this.camera = new PerspectiveCamera(fov, window.innerWidth / window.innerHeight, 0.1, 1000);
    this.camera.position.set(0, 0, 3);
    this.camera.lookAt(0, 0, 0);

    // Lights
    this.scene.add(new AmbientLight(0xffffff, 0.6));
    const dl = new DirectionalLight(0xffffff, 1);
    dl.position.set(5, 5, 10);
    this.scene.add(dl);

    // Geometry — pseudo-icosahedron déformable (12 sommets + pointes)
    const geometry = new BufferGeometry();
    const base = this._generateBaseGeometry();
    geometry.setAttribute('position', new Float32BufferAttribute(base.pos, 3));
    geometry.setAttribute('normal', new Float32BufferAttribute(base.normals, 3));
    geometry.computeVertexNormals();

    const material = new THREE.MeshPhysicalMaterial({
      color: 0x88ccff,
      metalness: 0.1,
      roughness: 0.0,
      transmission: 0.9,
      thickness: 1.5,
      transparent: true,
      opacity: 0.9,
      side: THREE.DoubleSide
    });

    this.mesh = new Mesh(geometry, material);
    this.scene.add(this.mesh);

    // Arêtes lumineuses
    const edges = this._extractEdges(geometry);
    const edgesGeom = new BufferGeometry();
    edgesGeom.setAttribute('position', new Float32BufferAttribute(edges, 3));
    const edgesMat = new LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.6 });
    this.edges = new LineSegments(edgesGeom, edgesMat);
    this.scene.add(this.edges);

    // Pointes
    const pointsGeom = new BufferGeometry();
    pointsGeom.setAttribute('position', new Float32BufferAttribute(base.points, 3));
    const pointsMat = new PointsMaterial({ color: 0xffffff, size: 0.12, sizeAttenuation: true });
    this.points = new Points(pointsGeom, pointsMat);
    this.scene.add(this.points);

    // Animation state
    this.state = {
      listening: 0.2,
      thinking: 0.2,
      speaking: 0.2
    };
    this.animationId = null;
    this.frames = 0;
    this.bands = new Float32Array(16).fill(0);
    this.deformation = 1;
    this.isPaused = false;
    this._initDeformations();

    // Audio
    this.audioContext = null;
    this.analyser = null;
    this.simulation = false;

    // ResizeObserver
    this.resizeObserver = new ResizeObserver(() => this._onResize());
    this.resizeObserver.observe(canvas);

    this._loop();
