      0,2, 2,6, 6,5, 5,1,
      1,7, 7,5, 2,3, 3,6,
      3,7, 7,6, 6,2,
      4,8, 8,10, 10,4,
      5,9, 9,8, 8,5,
      6,9, 9,10, 10,6,
      7,9, 9,11, 11,7,
      8,10, 10,11, 11,8,
      0,4, 2,0, 3,2
    ];
    for (const i of idx) {
      const p = pos.slice(i * 3, i * 3 + 3);
      edges.push(...p);
    }
    return edges;
  }

  _initDeformations() {
    this.deformations = {
      vertices: new Float32Array(36),
      pointes: new Float32Array(24),
      silhouette: new Float32Array(12)
