import * as THREE from './vendor/three.module.js';

const _audioContextMap = new WeakMap();
const _defaultContext = typeof AudioContext !== 'undefined' ? new AudioContext() : null;

export default class CrystalOrb {
  constructor(canvas) {
    this._canvas = canvas;
    this._container = canvas.parentElement;
    this._state = 'listening';
    this._simulation = false;
    this._bands = new Float32Array(16).fill(0);
    this._deformation = 0;
    this._frames = 0;
    this._renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance' });
    this._renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this._renderer.setSize(this._container.clientWidth, this._container.clientHeight, false);
    this._renderer.setClearColor(0x000000, 0);

    const scene = new THREE.Scene();
    scene.background = null;

    // Geometry: non-indexed, base copy for deformation
    const baseGeo = new THREE.IcosahedronGeometry(1, 1).toNonIndexed();
    this._basePositions = baseGeo.attributes.position.clone();

    // Vertex colors varied per vertex
    const count = this._basePositions.count;
    const colors = [];
    for (let i = 0; i < count; i++) {
      const hue = (i / count) * Math.PI;
      const rgb = new THREE.Color();
      rgb.setHSL((Math.sin(hue) + 1) * 0.5, 0.8, (Math.cos(hue) + 1) * 0.25);
      colors.push(rgb.r, rgb.g, rgb.b);
    }
    this._basePositions.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

    // Deformation helper
    const basePos = this._basePositions.array;
    const positions = new Float32Array(basePos.length);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color', this._basePositions.getAttribute('color').clone());

    const material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      metalness: 0.35,
      roughness: 0.25,
      transparent: true,
      opacity: 0.5,
      flatShading: true,
      vertexColors: true,
      emissive: 0x222222,
      emissiveIntensity: 0.1,
      side: THREE.DoubleSide
    });

    const mesh = new THREE.Mesh(geo, material);
    mesh.frustumCulled = false;

    // Wireframe overlay
    const wireGeo = new THREE.WireframeGeometry(geo);
    const wireMat = new THREE.MeshBasicMaterial({
      color: 0xaaccff,
      transparent: true,
      opacity: 0.25,
      depthTest: false
    });
    const wireframe = new THREE.LineSegments(wireGeo, wireMat);
    wireframe.frustumCulled = false;

    this._orbGroup = new THREE.Group();
    this._orbGroup.add(mesh);
    this._orbGroup.add(wireframe);
    scene.add(this._orbGroup);

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.7);
    dirLight.position.set(2, 2, 3);
    scene.add(dirLight);

    const pointLight = new THREE.PointLight(0x66ccff, 0.8, 10);
    pointLight.position.set(-2, -1, 2);
    scene.add(pointLight);

    this._camera = new THREE.PerspectiveCamera(45, this._container.clientWidth / this._container.clientHeight, 0.1, 100);
    this._camera.position.set(0, 0, 3.6);

    this._scene = scene;

    // Animation loop
    this._rafId = null;
    this._lastFrameTime = 0;
    this._animating = true;

    this._resizeObserver = new ResizeObserver(entries => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        this._renderer.setSize(width, height, false);
        const aspect = width / height;
        this._camera.aspect = aspect;
        this._camera.updateProjectionMatrix();
      }
    });
    this._resizeObserver.observe(this._container);

    this._frameCallback = this._animate.bind(this);
    this._startLoop();
  }

  setState(state) {
    if (state === 'listening' || state === 'thinking' || state === 'speaking') {
      this._state = state;
    }
  }

  attachAudio(audioElement) {
    if (!audioElement || !(_audioContextMap.has(audioElement) ? _audioContextMap.get(audioElement).ctx : _defaultContext)) return;

    let ctx = _audioContextMap.get(audioElement)?.ctx;
    if (!ctx) {
      ctx = _defaultContext || new AudioContext();
      _audioContextMap.set(audioElement, { ctx, source: null });
    }
    if (!ctx.state) ctx.resume?.();

    if (!audioElement.paused && ctx.state === 'suspended') ctx.resume();

    if (!_audioContextMap.get(audioElement).source) {
      try {
        const src = ctx.createMediaElementSource(audioElement);
        _audioContextMap.get(audioElement).source = src;
        src.connect(ctx.destination);
      } catch (e) {
        // MediaElementSource may throw if already connected; ignore
      }
    }

    this._setupAnalyser(ctx);
  }

  attachStream(stream) {
    const ctx = _defaultContext || new AudioContext();
    if (!ctx.state) ctx.resume?.();
    if (stream.getAudioTracks().length === 0) return;

    const analyser = ctx.createAnalyser();
    analyser.fftSize = 2048;
    const gain = ctx.createGain();
    gain.gain.value = 0;

    // Connect stream inputs
    const source = ctx.createMediaStreamSource(stream);
    source.connect(analyser);
    analyser.connect(gain);
    gain.connect(ctx.destination);

    this._analyser = analyser;
    this._audioCtx = ctx;
  }

  setSimulation(enabled) {
    this._simulation = enabled;
  }

  get diagnostics() {
    return {
      frames: this._frames,
      state: this._state,
      bands: Array.from(this._bands),
      deformation: this._deformation,
      renderer: 'webgl'
    };
  }

  dispose() {
    this._animating = false;
    if (this._rafId) {
      cancelAnimationFrame(this._rafId);
      this._rafId = null;
    }
    this._resizeObserver.disconnect();
    this._renderer.dispose();
    this._orbGroup = null;
    this._scene = null;
    this._camera = null;
  }

  _setupAnalyser(ctx) {
    if (!ctx) return;
    if (this._analyser && this._analyser.context === ctx) return;
    this._analyser = ctx.createAnalyser();
    this._analyser.fftSize = 2048;
    const source = ctx.createMediaElementSource(this._audioElement);
    source.connect(this._analyser);
    this._analyser.connect(ctx.destination);
  }

  _animate(timestamp) {
    if (!this._animating) return;

    const now = performance.now();
    const delta = now - this._lastFrameTime;
    const fpsCap = 30;
    const minFrameTime = 1000 / fpsCap;

    if (delta >= minFrameTime) {
      this._frames++;
      this._lastFrameTime = now;
      this._updateStateAndDeformation(now);
      this._updateVisuals();
      this._renderer.render(this._scene, this._camera);
    } else if (document.hidden) {
      // Low frequency in background tab
      this._rafId = requestAnimationFrame(this._frameCallback);
      return;
    }

    this._rafId = requestAnimationFrame(this._frameCallback);
  }

  _updateStateAndDeformation(now) {
    // Base oscillation per state
    const baseSpeed = now * 0.002;
    const baseAmp = this._state === 'speaking' ? 0.15 : this._state === 'thinking' ? 0.05 : 0.02;
    let energy = 0;

    // Audio energy (if analyser available)
    if (this._analyser) {
      const buffer = new Uint8Array(this._analyser.frequencyBinCount);
      this._analyser.getByteFrequencyData(buffer);
      const len = buffer.length;
      const bands = this._bands;

      // Aggregate into 16 bands
      for (let i = 0; i < 16; i++) {
        const start = Math.floor((i * len) / 16);
        const end = Math.floor(((i + 1) * len) / 16);
        let sum = 0;
        for (let j = start; j < end; j++) {
          sum += buffer[j];
        }
        const avg = sum / (end - start);
        const normalized = Math.min(avg / 255, 1);
        bands[i] = bands[i] * 0.9 + normalized * 0.1; // smoothing
      }

      // Weighted energy (bass/mid/treble)
      const bass = bands.slice(0, 4).reduce((a, b) => a + b, 0) / 4;
      const mid = bands.slice(4, 10).reduce((a, b) => a + b, 0) / 6;
      const treble = bands.slice(10, 16).reduce((a, b) => a + b, 0) / 6;
      energy = Math.sqrt(bass * 0.6 + mid * 0.3 + treble * 0.1);

      // Pulse simulation (if no real audio)
      if (this._simulation) {
        const simPulse = (Math.sin(now * 0.005) + 1) * 0.5;
        energy = Math.max(energy, simPulse);
      }
    } else {
      // Idle idle
      energy = 0;
    }

    // Deformation pattern
    const rotSpeed = this._state === 'speaking' ? 0.02 : 0.005;
    this._orbGroup.rotation.y += rotSpeed;
    this._orbGroup.rotation.z += rotSpeed * 0.5;

    // Base oscillation
    const baseDeform = baseAmp * (1 + Math.sin(baseSpeed) * 0.3 + Math.cos(baseSpeed * 1.3) * 0.2);
    this._deformation = baseDeform + energy * (this._state === 'speaking' ? 0.4 : this._state === 'thinking' ? 0.2 : 0.1);
  }

  _updateVisuals() {
    const geo = this._orbGroup.children[0].geometry;
    const basePos = this._basePositions.array;
    const outPos = geo.attributes.position.array;
    const deformed = this._deformation;

    // Random irregularity (fixed per vertex via hash)
    const count = this._basePositions.count;
    for (let i = 0; i < count; i++) {
      const vx = basePos[i * 3];
      const vy = basePos[i * 3 + 1];
      const vz = basePos[i * 3 + 2];

      // Radial distance
      const dist = Math.sqrt(vx * vx + vy * vy + vz * vz);
      const dirX = vx / dist;
      const dirY = vy / dist;
      const dirZ = vz / dist;

      // Simple vertex-index-based hash for irregularity
      const hash = Math.sin(i * 12.9898 + deformed * 0.5) * 43758.5453;
      const noise = (hash - Math.floor(hash)) * 0.5;

      // Energy-based modulation (using band 0 for bass)
      const bassMod = this._bands[0] || 0;

      // Final scale factor per vertex
      const scale = 1 + deformed * (1 + bassMod * 0.8 + noise * 0.4);

      outPos[i * 3] = vx * scale;
      outPos[i * 3 + 1] = vy * scale;
      outPos[i * 3 + 2] = vz * scale;
    }
    geo.attributes.position.needsUpdate = true;
  }
}

import * as THREE from './vendor/three.module.js';

export class CrystalOrb {
  constructor(canvas) {
    this._canvas = canvas;
    this._state = 'listening';
    this._bands = new Array(16).fill(0);
    this._deformation = 0;
    this._isSimulating = false;

    this._ctx = null;
    this._analyser = null;
    this._map = new WeakMap();

    const parent = canvas.parentElement;
    this._resizeObserver = new ResizeObserver(entries => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        this._renderer.setSize(width, height, false);
        this._camera.aspect = width / height;
        this._camera.updateProjectionMatrix();
      }
    });
    this._resizeObserver.observe(parent);

    const geo = new THREE.IcosahedronGeometry(1, 1);
    this._base = new Float32Array(geo.attributes.position.array);
    const colors = new Float32Array(this._base.length);
    for (let i = 0; i < this._base.length; i += 3) {
      const x = this._base[i], y = this._base[i + 1], z = this._base[i + 2];
      const r = (x + 1) * 0.5, g = (y + 1) * 0.5, b = (z + 1) * 0.5;
      colors[i] = r; colors[i + 1] = g; colors[i + 2] = b;
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.computeVertexNormals();

    this._wireGeo = new THREE.WireframeGeometry(geo);
    const wirePositions = this._wireGeo.attributes.position.array;
    const wireColors = new Float32Array(wirePositions.length);
    for (let i = 0; i < wirePositions.length; i += 3) {
      const x = wirePositions[i], y = wirePositions[i + 1], z = wirePositions[i + 2];
      const r = (x + 1) * 0.5, g = (y + 1) * 0.5, b = (z + 1) * 0.5;
      wireColors[i] = r; wireColors[i + 1] = g; wireColors[i + 2] = b;
    }
    this._wireGeo.setAttribute('color', new THREE.BufferAttribute(wireColors, 3));

    const material = new THREE.MeshStandardMaterial({
      transparent: true,
      opacity: 0.5,
      metalness: 0.35,
      roughness: 0.25,
      flatShading: true,
      vertexColors: true
    });

    const wireMaterial = new THREE.LineBasicMaterial({ vertexColors: true });

    this._mesh = new THREE.Mesh(geo, material);
    this._wire = new THREE.LineSegments(this._wireGeo, wireMaterial);

    this._group = new THREE.Group();
    this._group.add(this._mesh);
    this._group.add(this._wire);

    this._scene = new THREE.Scene();
    this._scene.add(this._group);

    const light1 = new THREE.DirectionalLight(0xffffff, 1.2);
    light1.position.set(1, 1, 1);
    const light2 = new THREE.DirectionalLight(0x4488ff, 0.8);
    light2.position.set(-1, -0.5, 0.5);
    this._scene.add(light1, light2);

    this._camera = new THREE.PerspectiveCamera(45, parent.clientWidth / parent.clientHeight, 0.1, 10);
    this._camera.position.z = 3.6;

    this._renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
    this._renderer.setSize(parent.clientWidth, parent.clientHeight, false);
    this._renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));

    const tick = (t) => {
      if (this._rafId) this._rafId = requestAnimationFrame(tick);
      if (!this._rafId) return;

      const time = t * 0.001;
      this._update(time);
    };
    this._rafId = requestAnimationFrame(tick);

    this._stateColors = {
      listening: [0.1, 0.4, 0.9],
      thinking: [0.9, 0.3, 0.2],
      speaking: [0.2, 0.9, 0.3]
    };
  }

  setState(state) {
    if (!['listening', 'thinking', 'speaking'].includes(state)) return;
    this._state = state;
  }

  attachAudio(audioElement) {
    if (!this._ctx) {
      this._ctx = new (window.AudioContext || window.webkitAudioContext)();
    }
    this._ctx.resume();

    if (!this._analyser) {
      this._analyser = this._ctx.createAnalyser();
      this._analyser.fftSize = 2048;
      this._analyser.smoothingTimeConstant = 0.85;
    }

    let src = this._map.get(audioElement);
    if (!src) {
      src = this._ctx.createMediaElementSource(audioElement);
      this._map.set(audioElement, src);
    }
    src.disconnect();
    src.connect(this._analyser);
    this._analyser.connect(this._ctx.destination);
  }

  attachStream(stream) {
    if (!this._ctx) {
      this._ctx = new (window.AudioContext || window.webkitAudioContext)();
    }
    this._ctx.resume();

    if (!this._analyser) {
      this._analyser = this._ctx.createAnalyser();
      this._analyser.fftSize = 2048;
      this._analyser.smoothingTimeConstant = 0.85;
    }

    const gain = this._ctx.createGain();
    gain.gain.value = 0;
    stream.getTracks().forEach(track => track.stop());

    const src = this._ctx.createMediaStreamSource(stream);
    src.connect(this._analyser);
    this._analyser.connect(gain);
    gain.connect(this._ctx.destination);
  }

  setSimulation(enabled) {
    this._isSimulating = enabled;
  }

  _update(time) {
    if (this._analyser && !this._isSimulating) {
      const buffer = new Uint8Array(this._analyser.frequencyBinCount);
      this._analyser.getByteFrequencyData(buffer);

      const n = 16;
      const step = buffer.length / n;
      for (let i = 0; i < n; i++) {
        let sum = 0;
        for (let j = 0; j < step; j++) {
          sum += buffer[Math.floor(i * step + j)];
        }
        const avg = sum / step / 255;
        this._bands[i] = this._bands[i] * 0.85 + avg * 0.15;
      }
    } else if (this._isSimulating) {
      for (let i = 0; i < 16; i++) {
        const wave = Math.sin(time * (i + 1) * 2 + i);
        this._bands[i] = Math.max(0, (wave + 1) * 0.5);
      }
    }

    const low = (this._bands[0] + this._bands[1] + this._bands[2]) / 3;
    const mid = (this._bands[4] + this._bands[5] + this._bands[6]) / 3;
    const high = (this._bands[12] + this._bands[13] + this._bands[14]) / 3;
    const baseGain = 0.2;

    const positions = this._mesh.geometry.attributes.position.array;
    const colors = this._mesh.geometry.attributes.color.array;
    const base = this._base;

    const rgb = this._stateColors[this._state];

    for (let i = 0; i < positions.length; i += 3) {
      const x = base[i], y = base[i + 1], z = base[i + 2];
      const r = Math.sqrt(x * x + y * y + z * z);
      const factor = baseGain + low * (0.5 + 0.5 * Math.abs(x)) + mid * (0.3 + 0.2 * Math.abs(y)) + high * (0.3 + 0.2 * Math.abs(z)) + 0.07 * Math.sin(x * 5 + time);
      const scale = 1 + factor;

      const nx = x * scale, ny = y * scale, nz = z * scale;
      positions[i] = nx; positions[i + 1] = ny; positions[i + 2] = nz;

      const noise = 0.5 + 0.5 * (Math.sin(x * 3 + time) + Math.cos(y * 3 + time));
      const shade = (1 - nz / r) * 0.4 + 0.6;
      const rC = rgb[0] * shade * (0.7 + 0.3 * noise);
      const gC = rgb[1] * shade * (0.7 + 0.3 * noise);
      const bC = rgb[2] * shade * (0.7 + 0.3 * noise);

      colors[i] = rC; colors[i + 1] = gC; colors[i + 2] = bC;
    }

    this._mesh.geometry.attributes.position.needsUpdate = true;
    this._mesh.geometry.attributes.color.needsUpdate = true;
    this._mesh.geometry.computeVertexNormals();

    const wirePositions = this._wireGeo.attributes.position.array;
    const wireColors = this._wireGeo.attributes.color.array;
    for (let i = 0; i < wirePositions.length; i += 3) {
      const x = base[i], y = base[i + 1], z = base[i + 2];
      const factor = baseGain + low * (0.5 + 0.5 * Math.abs(x)) + mid * (0.3 + 0.2 * Math.abs(y)) + high * (0.3 + 0.2 * Math.abs(z));
      const scale = 1 + factor;
      wirePositions[i] = x * scale;
      wirePositions[i + 1] = y * scale;
      wirePositions[i + 2] = z * scale;

      const noise = 0.5 + 0.5 * (Math.sin(x * 3 + time) + Math.cos(y * 3 + time));
      const shade = (1 - z / Math.sqrt(x * x + y * y + z * z)) * 0.4 + 0.6;
      wireColors[i] = rgb[0] * shade * (0.7 + 0.3 * noise);
      wireColors[i + 1] = rgb[1] * shade * (0.7 + 0.3 * noise);
      wireColors[i + 2] = rgb[2] * shade * (0.7 + 0.3 * noise);
    }

    this._wireGeo.attributes.position.needsUpdate = true;
    this._wireGeo.attributes.color.needsUpdate = true;

    this._group.rotation.y = time * 0.2;
    this._group.rotation.z = time * 0.05;

    this._deformation = Math.max(low, mid, high);
    this._diagnostics = {
      frames: 0,
      state: this._state,
      bands: [...this._bands],
      deformation: this._deformation,
      renderer: 'webgl'
    };
  }

  get diagnostics() {
    return this._diagnostics || { frames: 0, state: this._state, bands: [0]*16, deformation: 0, renderer: 'webgl' };
  }

  dispose() {
    if (this._rafId) cancelAnimationFrame(this._rafId);
    this._rafId = null;
    this._resizeObserver.disconnect();
    this._renderer.forceContextLoss();
    this._renderer.dispose();
    if (this._ctx && this._ctx.state !== 'closed') {
      // Ne pas fermer le contexte global — on ne contrôle pas les pistes externes
    }
  }
}

export default CrystalOrb;

