/* JL03 — Interface principale */
:root {
  --navy-dark: #0a192f;
  --navy: #112240;
  --navy-light: #233554;
  --text-main: #e6f1ff;
  --text-muted: #8892b0;
  --accent-turquoise: #64ffda;
  --accent-turquoise-dim: #3eb2b5;
  --glass: rgba(10, 25, 47, 0.8);
  --glass-border: rgba(100, 255, 218, 0.15);
  --orb-bg: radial-gradient(circle at center, #0d263d, #071424);
  --orb-border: linear-gradient(45deg, rgba(100, 255, 218, 0.3), rgba(100, 255, 218, 0.05));
  --orb-glow: radial-gradient(circle, rgba(100, 255, 218, 0.2), transparent 60%);
  --orb-running: radial-gradient(circle, rgba(255, 71, 87, 0.2), transparent 60%);
  --orb-idle: radial-gradient(circle, rgba(100, 255, 218, 0.2), transparent 60%);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100vh; overflow: hidden; background-color: var(--navy-dark); color: var(--text-main); font-family: 'Inter', system-ui, -apple-system, sans-serif; }
body { display: flex; }

/* Layout principal */
#app { display: flex; width: 100vw; height: 100vh; }

/* Sidebar (gauche, masquable) */
#sidebar {
  width: 260px; flex-shrink: 0; background: var(--navy); border-right: 1px solid var(--glass-border);
  display: flex; flex-direction: column; transition: transform 0.3s ease; position: relative;
}
#sidebar.hidden { transform: translateX(-100%); }

#menu-btn {
  position: absolute; top: 16px; left: 16px; z-index: 1000; background: none; border: none; color: var(--text-main);
  font-size: 24px; cursor: pointer; display: none;
}
@media (max-width: 768px) { #menu-btn { display: block; } }
#sidebar-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5);
  z-index: 999; display: none;
}
#sidebar-overlay.active { display: block; }

#sidebar-header {
  padding: 20px 16px; border-bottom: 1px solid var(--glass-border); display: flex; align-items: center; gap: 12px;
}
#sidebar-header h1 { font-size: 16px; color: var(--accent-turquoise); letter-spacing: 1px; text-transform: uppercase; }

#sidebar-scroll { flex: 1; overflow-y: auto; padding: 16px; }
#sidebar-section { margin-bottom: 24px; }
#sidebar-section h2 { font-size: 12px; color: var(--text-muted); text-transform: uppercase; margin-bottom: 12px; }
#sidebar-actions { display: flex; flex-direction: column; gap: 8px; }
.sidebar-btn {
  display: flex; align-items: center; gap: 12px; background: var(--navy-light); border: 1px solid var(--glass-border);
  color: var(--text-main); padding: 10px 12px; border-radius: 8px; cursor: pointer; font: inherit;
  transition: all 0.2s;
}
.sidebar-btn:hover { background: rgba(100, 255, 218, 0.05); border-color: var(--accent-turquoise-dim); }
.sidebar-btn .icon { font-size: 16px; color: var(--accent-turquoise); }

#recent-conversations .sidebar-btn { justify-content: space-between; }

/* Main content */
#main { flex: 1; display: flex; flex-direction: column; position: relative; }

#telemetry { height: 36px; background: var(--navy); border-bottom: 1px solid var(--glass-border); display: flex; align-items: center; padding: 0 16px; font-size: 12px; color: var(--text-muted); }

#content { flex: 1; overflow: hidden; display: flex; position: relative; }

/* Canvas orbital */
#orb-container {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;
  display: flex; align-items: center; justify-content: center;
}
#orb {
  width: 240px; height: 240px; border-radius: 50%; position: relative; z-index: 10;
  background: var(--orb-bg); border: 1px solid var(--glass-border);
  box-shadow: 0 0 80px 20px rgba(0,0,0,0.6), inset 0 0 120px rgba(255,255,255,0.03);
}
#orb::before {
  content: ''; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 120%; height: 120%; border-radius: 50%; background: var(--orb-glow); opacity: 0;
  transition: opacity 0.5s; pointer-events: none; z-index: 9;
}
#orb.idle::before { opacity: 1; animation: pulse 8s infinite; }
#orb.running { border-color: rgba(255,71,87,0.4); }
#orb.running::before { background: var(--orb-running); opacity: 1; }
#orb.waiting { border-color: rgba(100,255,218,0.4); }
#orb.waiting::before { background: var(--orb-idle); opacity: 1; }

@keyframes pulse {
  0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.2; }
  50% { transform: translate(-50%, -50%) scale(1.1); opacity: 0.5; }
}

#orb-facets {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;
  mask-image: radial-gradient(circle, black 45%, transparent 60%);
  -webkit-mask-image: radial-gradient(circle, black 45%, transparent 60%);
}
.facet { position: absolute; background: var(--glass-border); opacity: 0.15; transform-origin: center; }
.facet:nth-child(1) { width: 100%; height: 1px; top: 50%; left: 0; }
.facet:nth-child(2) { width: 1px; height: 100%; left: 50%; top: 0; }
.facet:nth-child(3) { width: 70%; height: 1px; top: 50%; left: 15%; transform: rotate(45deg); }
.facet:nth-child(4) { width: 70%; height: 1px; top: 50%; left: 15%; transform: rotate(-45deg); }
.facet:nth-child(5) { width: 40%; height: 1px; top: 50%; left: 30%; transform: rotate(22.5deg); }
.facet:nth-child(6) { width: 40%; height: 1px; top: 50%; left: 30%; transform: rotate(-22.5deg); }

/* Chat area */
#chat-container {
  flex: 1; overflow: hidden; display: flex; flex-direction: column; position: relative; z-index: 20;
  padding: 0 24px 120px 24px; margin: 0 auto; max-width: 960px; width: 100%;
}
#chat-history {
  flex: 1; overflow-y: auto; padding-top: 24px; display: flex; flex-direction: column; gap: 16px;
}
#chat-history::-webkit-scrollbar { width: 8px; }
#chat-history::-webkit-scrollbar-track { background: transparent; }
#chat-history::-webkit-scrollbar-thumb { background: var(--navy-light); border-radius: 4px; }

.message { display: flex; gap: 16px; max-width: 90%; }
.message.user { align-self: flex-end; flex-direction: row-reverse; }
.message.assistant { align-self: flex-start; }
.message-content { padding: 12px 16px; border-radius: 16px; line-height: 1.5; }
.user .message-content { background: var(--navy-light); }
.assistant .message-content { background: var(--glass); border: 1px solid var(--glass-border); }
.message .user-label, .message .assistant-label {
  font-size: 12px; color: var(--text-muted); margin-bottom: 4px;
}

/* Input area */
#input-area {
  position: absolute; bottom: 0; left: 0; right: 0; background: linear-gradient(to top, var(--navy-dark) 20%, transparent);
  padding: 24px 24px 24px 24px; display: flex; flex-direction: column; gap: 12px; align-items: center;
}
#input-container {
  width: 100%; max-width: 960px; position: relative;
}
#input-textarea {
  width: 100%; min-height: 56px; max-height: 180px; padding: 12px 60px 12px 16px; background: var(--navy-light);
  border: 1px solid var(--glass-border); border-radius: 12px; color: var(--text-main); font: inherit; resize: none;
  outline: none; overflow-y: hidden;
}
#input-textarea:focus { border-color: var(--accent-turquoise-dim); }
#input-tools {
  position: absolute; right: 12px; bottom: 12px; display: flex; gap: 8px;
}
#mic-btn, #send-btn {
  width: 36px; height: 36px; border-radius: 50%; border: none; cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: all 0.2s;
}
#mic-btn { background: var(--glass); border: 1px solid var(--glass-border); color: var(--text-main); }
#mic-btn.active { background: var(--accent-turquoise); color: var(--navy-dark); }
#mic-btn.listening { background: #ff4757; color: white; }
#send-btn { background: var(--accent-turquoise); color: var(--navy-dark); }
#mic-btn:hover, #send-btn:hover { transform: scale(1.05); }

#status-bar {
  display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-muted); min-height: 20px;
}
#status-bar .dot { width: 8px; height: 8px; border-radius: 50%; }
#status-bar .dot.idle { background: var(--accent-turquoise); }
#status-bar .dot.waiting { background: #60a5fa; }
#status-bar .dot.busy { background: #ff4757; }
#status-bar .text { opacity: 0; transition: opacity 0.3s; }
#status-bar .text.visible { opacity: 1; }

/* Mission panel */
#mission-panel {
  position: absolute; bottom: 120px; right: 24px; width: 320px; max-height: 60vh;
  background: var(--navy); border: 1px solid var(--glass-border); border-radius: 12px;
  box-shadow: 0 12px 48px rgba(0,0,0,0.6); z-index: 50; overflow: hidden;
  display: flex; flex-direction: column; resize: vertical;
}
#mission-panel.hidden { display: none; }
#mission-header {
  display: flex; justify-content: space-between; align-items: center; padding: 10px 16px; border-bottom: 1px solid var(--glass-border);
  background: var(--navy-light); cursor: n-resize;
}
#mission-title { font-size: 13px; color: var(--text-main); font-weight: 500; display: flex; align-items: center; gap: 8px; }
#mission-toggle { background: none; border: none; color: var(--text-muted); cursor: pointer; }
#mission-events {
  flex: 1; overflow-y: auto; padding: 12px; font-size: 12px; display: flex; flex-direction: column; gap: 8px;
}
#mission-select-container { padding: 8px 16px; border-top: 1px solid var(--glass-border); }
#mission-select {
  width: 100%; padding: 6px; background: var(--navy-dark); border: 1px solid var(--glass-border); color: var(--text-main); border-radius: 6px; font: inherit;
}

/* Animations */
@keyframes typing {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}
.typing::after {
  content: '...'; animation: typing 1.5s infinite;
}

/* Responsive */
@media (max-width: 960px) {
  #app { flex-direction: column; }
  #sidebar { position: fixed; top: 0; left: 0; height: 100%; z-index: 1000; }
  #orb-container { position: fixed; top: 12%; left: 24%; width: 180px; height: 180px; }
}

