import { api, artifactURL } from './api.js';
import { CrystalOrb } from './orb.js';

constorb = new CrystalOrb(document.getElementById('orb'));
const cfg = { default_model: null };
const state = {
  session: null,
  conversations: [],
  projects: [],
  currentConversation: null,
  currentProject: null,
  pendingRetry: null
};

// Utility: DOM helpers
function $(id) { return document.getElementById(id); }
function createEl(tag, { id, className, text } = {}) {
  const el = document.createElement(tag);
  if (id) el.id = id;
  if (className) el.className = className;
  if (text) el.textContent = text;
  return el;
}

// UI elements
const els = {
  menuToggle: $('menu-toggle'),
  sidebar: $('sidebar'),
  newConversationBtn: $('new-conversation-btn'),
  projectSelect: $('project-select'),
  projectCreate: $('project-create'),
  projectCreateBtn: $('project-create-btn'),
  conversationSelect: $('conversation-select'),
  renameConversationBtn: $('rename-conversation-btn'),
  libraryBtn: $('library-btn'),
  settingsBtn: $('settings-btn'),
  messages: $('messages'),
  promptInput: $('prompt-input'),
  voiceBtn: $('voice-btn'),
  stopAudioBtn: createEl('button', { className: 'stop-audio-btn', text: '⏹️' }),
  sendBtn: $('send-btn'),
  missionPanel: $('mission-panel'),
  missionSelect: $('mission-select'),
  missionToggle: $('mission-toggle'),
  missionEvents: $('mission-events'),
  missionLaunch: $('mission-launch'),
  statusText: $('status-text'),
  telemetry: $('telemetry')
};

els.stopAudioBtn.addEventListener('click', () => state.voiceCtrl?.interruptAudio?.());
state.voiceBtn?.addEventListener('click', () => toggleMic());
els.sendBtn.addEventListener('click', () => {
  const text = els.promptInput.value.trim();
  if (text) sendPrompt(text);
});
els.menuToggle?.addEventListener('click', () => els.sidebar.classList.toggle('hidden'));
els.missionToggle?.addEventListener('click', () => els.missionPanel.classList.toggle('hidden'));
els.renameConversationBtn?.addEventListener('click', renameCurrentConversation);
els.newConversationBtn?.addEventListener('click', createNewConversation);
els.projectCreateBtn?.addEventListener('click', createNewProject);

// Session & login
function showLogin() {
  const modal = createEl('div', { className: 'login-modal', id: 'login-modal' });
  modal.innerHTML = `
    <div class="modal-content">
      <h3>Connexion requise</h3>
      <form id="login-form">
        <label>Nom d'utilisateur :<input type="text" id="username" required></label>
        <label>Mot de passe :<input type="password" id="password" required></label>
        <button type="submit">Connexion</button>
      </form>
    </div>
  `;
  document.body.appendChild(modal);
  const form = modal.querySelector('form');
  form.onsubmit = async e => {
    e.preventDefault();
    const user = $('username').value.trim();
    const pass = $('password').value.trim();
    try {
      const res = await api('/api/login', { method: 'POST', body: { user, pass } });
      if (res.session) {
        state.session = res.session;
        document.body.removeChild(modal);
        await initApp();
      }
    } catch (err) {
      alert('Échec de la connexion : ' + err.message);
    }
  };
}

async function initApp() {
  try {
    const session = await api('/api/session');
    if (!session?.user) {
      showLogin();
      return;
    }
    state.session = session;
    const config = await api('/api/config');
    cfg.default_model = config?.default_model || 'qwen3-coder-next:q4_K_M';
    await loadConversationsAndProjects();
    initOptionalModules();
    // Poll telemetry every 10s
    setInterval(async () => {
      try {
        const data = await api('/api/launcher/resources');
        if (state.telemetryCtrl?.render) {
          state.telemetryCtrl.render(els.telemetry, data);
        } else if (data) {
          els.telemetry.textContent = JSON.stringify(data, null, 2);
        }
      } catch (e) {}
    }, 10000);
  } catch (e) {
    alert('Erreur critique : ' + e.message);
    throw e;
  }
}

// Conversations & projects
async function loadConversationsAndProjects() {
  try {
    const { conversations, projects } = await api('/api/v3/conversations');
    state.conversations = conversations || [];
    state.projects = projects || [];
    fillSelect(els.projectSelect, projects);
    fillSelect(els.conversationSelect, conversations.map(c => ({ id: c.id, title: c.title })));
    // Select first if none
    if (!state.currentConversation && conversations?.[0]?.id) {
      selectConversation(conversations[0].id, conversations[0].project);
    }
  } catch (e) {
    console.error('loadConversationsAndProjects failed', e);
  }
}

function fillSelect(select, items) {
  select.innerHTML = '';
  for (const item of items) {
    select.add(new Option(item.title ?? item.id, item.id));
  }
}

async function selectConversation(id, project = null) {
  if (!id) return;
  state.currentConversation = await api('/api/history', { id });
  state.currentProject = project;
  renderHistory();
}

function renderHistory() {
  els.messages.innerHTML = '';
  const hist = state.currentConversation || [];
  hist.forEach(msg => {
    const el = createEl('div', { className: `msg ${msg.role}` });
    el.textContent = msg.content;
    els.messages.appendChild(el);
  });
  els.messages.scrollTop = els.messages.scrollHeight;
}

async function createNewConversation() {
  const proj = els.projectSelect.value || state.projects[0];
  if (!proj) { alert('Créez d’abord un projet'); return; }
  try {
    const conv = await api('/api/v3/conversation', { method: 'POST', body: { project: proj } });
    if (conv?.id) {
      state.conversations.push({ id: conv.id, project: conv.project, title: 'Nouvelle conversation' });
      fillSelect(els.conversationSelect, state.conversations);
      selectConversation(conv.id, conv.project);
    }
  } catch (e) {
    console.error(e);
  }
}

async function createNewProject() {
  const name = prompt('Nom du projet :');
  if (!name) return;
  try {
    const res = await api('/api/v3/project', { method: 'POST', body: { name } });
    const projectName = res?.project;
    if (projectName) {
      state.projects.push(projectName);
      fillSelect(els.projectSelect, state.projects);
      fillSelect(els.conversationSelect, state.conversations);
    }
  } catch (e) {
    console.error(e);
  }
}

async function renameCurrentConversation() {
  if (!state.currentConversation || !state.currentConversation.id) return;
  const newTitle = prompt('Nouveau titre :', els.conversationSelect.selectedOptions[0]?.textContent || '');
  if (!newTitle) return;
  try {
    await api('/api/v3/rename', { method: 'POST', body: { id: state.currentConversation.id, title: newTitle } });
    const idx = state.conversations.findIndex(c => c.id === state.currentConversation.id);
    if (idx >= 0) {
      state.conversations[idx].title = newTitle;
      fillSelect(els.conversationSelect, state.conversations);
    }
  } catch (e) {
    console.error(e);
  }
}

// Chat
async function sendPrompt(text) {
  if (!text) return;
  // Add user message
  const userMsg = { role: 'user', content: text };
  state.currentConversation.push(userMsg);
  renderHistory();

  // UI: thinking
  orbe.setState('thinking');
  state.pendingRetry = text;
  try {
    const res = await api('/api/chat', {
      method: 'POST',
      body: {
        text,
        model: cfg.default_model,
        conversation: state.currentConversation.id,
        project: state.currentProject,
        retain: true,
        agent_mode: false
      }
    });
    if (res?.answer) {
      const assistantMsg = { role: 'assistant', content: res.answer };
      state.currentConversation.push(assistantMsg);
      renderHistory();
      state.pendingRetry = null;
      orbe.setState('listening');
    } else {
      throw new Error('Réponse vide');
    }
  } catch (e) {
    state.statusText.textContent = 'Erreur : ' + e.message + ' → ' + text;
    state.pendingRetry = text;
    orbe.setState('listening');
  }
}

// Mission launch
async function launchMission() {
  const goal = prompt('Objectif de la mission :');
  if (!goal) return;
  try {
    orbe.setState('thinking');
    const res = await api('/api/missions', {
      method: 'POST',
      body: {
        goal,
        model: 'qwen3-coder-next:q4_K_M',
        conversation: state.currentConversation?.id,
        project: state.currentProject
      }
    });
    const id = res?.id;
    if (id) {
      state.statusText.textContent = `Mission lancée : ${id}`;
      // Select console tab (assumed to exist)
      const consoleTab = document.querySelector('a[href="#mission-console"]');
      consoleTab?.click?.();
    }
  } catch (e) {
    state.statusText.textContent = 'Erreur mission : ' + e.message;
    orbe.setState('listening');
  }
}

els.missionLaunch.addEventListener('click', launchMission);

// Optional modules (dynamic import)
function initOptionalModules() {
  // console.js — MissionConsole
  (async () => {
    try {
      const mod = await import('./console.js');
      const consoleEl = document.getElementById('mission-console') || createEl('div', { id: 'mission-console' });
      if (!document.body.contains(consoleEl)) {
        els.missionEvents.appendChild(consoleEl);
      }
      state.consoleCtrl = new mod.MissionConsole({
        container: consoleEl,
        select: els.missionSelect,
        onState: st => orbe.setState(st === 'thinking' ? 'thinking' : orbe.state === 'speaking' ? 'speaking' : 'listening'),
        onActivity: msg => {
          state.statusText.textContent = msg;
          const msgEl = createEl('div', { className: 'mission-log' });
          msgEl.textContent = msg;
          els.missionEvents.appendChild(msgEl);
          els.missionEvents.scrollTop = els.missionEvents.scrollHeight;
        }
      });
      state.consoleCtrl?.start?.();
    } catch (e) {
      console.warn('console.js non disponible', e);
    }
  })();

  // voice.js — VoiceController
  (async () => {
    try {
      const mod = await import('./voice.js');
      state.voiceCtrl = new mod.VoiceController({
        onTranscript: text => sendPrompt(text),
        onState: st => {
          const s = st === 'recording' ? 'listening' : st === 'speaking' ? 'speaking' : 'listening';
          orbe.setState(s);
        },
        onAudio: audio => orbe.attachAudio?.(audio),
        onError: err => {
          console.error('Voice error', err);
          state.statusText.textContent = 'Erreur micro : ' + err.message;
        }
      });
      // Toggle mic initially stopped
      state.micEnabled = false;
      els.voiceBtn.textContent = '🎤';
    } catch (e) {
      console.warn('voice.js non disponible', e);
    }
  })();

  // telemetry.js — telemetry renderer
  (async () => {
    try {
      const mod = await import('./telemetry.js');
      state.telemetryCtrl = mod.renderTelemetry;
    } catch (e) {
      console.warn('telemetry.js non disponible', e);
    }
  })();

  // Library
  els.libraryBtn.addEventListener('click', async () => {
    const modal = createEl('div', { className: 'modal', id: 'library-modal' });
    modal.innerHTML = '<div class="modal-content"><h3>Bibliothèque</h3><ul id="library-list"></ul></div>';
    document.body.appendChild(modal);
    const list = $('library-list');
    try {
      const res = await api('/api/v3/library');
      for (const item of res || []) {
        const li = createEl('li');
        li.textContent = item.name;
        if (item.path?.toLowerCase().endsWith('.wav')) {
          li.appendChild(createEl('audio', { src: artifactURL(item.path), controls: true }));
        } else {
          const a = createEl('a', { href: artifactURL(item.path), target: '_blank' });
          a.textContent = 'Télécharger';
          li.appendChild(a);
        }
        list.appendChild(li);
      }
    } catch (e) {
      list.textContent = 'Erreur bibliothèque : ' + e.message;
    }
    modal.onclick = () => document.body.removeChild(modal);
  });

  // Settings
  els.settingsBtn.addEventListener('click', () => {
    const modal = createEl('div', { className: 'modal', id: 'settings-modal' });
    modal.innerHTML = `
      <div class="modal-content">
        <h3>Paramètres</h3>
        <ul>
          <li><a href="/prototype.html" target="_blank">Prototype</a></li>
          <li><a href="https://github.com/codex/jl03" target="_blank">Dépôt GitHub</a></li>
          <li>SSH : ${document.body.dataset.ssh || 'non configuré'}</li>
          <li>Codex : ${document.body.dataset.codex || 'non configuré'}</li>
          <li>tmux sessions : ${document.body.dataset.tmux || 'non configuré'}</li>
        </ul>
        <label><input type="checkbox" id="autoplay"> Lecture automatique (désactivée par défaut)</label>
      </div>`;
    document.body.appendChild(modal);
    $('settings-modal').onclick = () => document.body.removeChild(modal);
  });

  // Search
  const searchBtn = createEl('button', { text: '🔍', className: 'search-btn' });
  searchBtn.addEventListener('click', async () => {
    const q = prompt('Recherche dans les messages :');
    if (!q) return;
    try {
      const res = await api('/api/search', { q, type: 'messages' });
      const results = res?.results || [];
      const modal = createEl('div', { className: 'modal', id: 'search-modal' });
      const list = createEl('ul');
      results.forEach(item => {
        const li = createEl('li');
        li.textContent = `[${item.project}] ${item.title} — ${item.content}`;
        list.appendChild(li);
      });
      modal.innerHTML = '<div class="modal-content"><h3>Résultats</h3></div>';
      modal.querySelector('.modal-content').appendChild(list);
      document.body.appendChild(modal);
      modal.onclick = () => document.body.removeChild(modal);
    } catch (e) {
      alert('Erreur recherche : ' + e.message);
    }
  });
  document.querySelector('.header')?.appendChild(searchBtn);
}

// Mic toggle
function toggleMic() {
  if (!state.micEnabled) {
    state.micEnabled = true;
    els.voiceBtn.textContent = '🔴';
    state.voiceCtrl?.startMic?.();
  } else {
    state.micEnabled = false;
    els.voiceBtn.textContent = '🎤';
    state.voiceCtrl?.stopMic?.();
  }
}

// Expose
window.jl03 = { orb, sendPrompt, state, api };

// Init
window.addEventListener('load', initApp);

import { api, artifactURL } from './api.js';

/**
 * MissionConsole — flux intégral chronologique et persistant des événements de mission.
 * Contrat : constructor({container,select,onState,onActivity}), start(), selectMission(id), stop()
 * Détails : pas de slice/troncature, pas d'affichage par défaut des resultats comme preuve interne, pas de données simulées.
 */
export class MissionConsole {
  #container;
  #select;
  #onState;
  #onActivity;
  #missions = [];
  #currentMissionId = null;
  #eventsMap = new Map(); // missionId → { events: [], cursor: string|null }
  #polling = false;
  #pollTimer = null;
  #autoscroll = true;
  #pollInterval = 2000;

  constructor({ container, select, onState, onActivity }) {
    this.#container = container;
    this.#select = select;
    this.#onState = onState;
    this.#onActivity = onActivity;
    this.#select.addEventListener('change', (e) => this.selectMission(e.target.value));
    this.#container.addEventListener('scroll', () => {
      const { scrollTop, scrollHeight, clientHeight } = this.#container;
      this.#autoscroll = Math.abs(scrollTop - (scrollHeight - clientHeight)) < 10;
    });
  }

  async start() {
    if (this.#polling) return;
    this.#polling = true;
    await this.#loadMissions();
    await this.#restoreSelection();
    this.#schedulePoll();
    this.#onActivity('Consulter le panneau pour suivre l’activité en temps réel.');
  }

  stop() {
    this.#polling = false;
    if (this.#pollTimer) {
      clearTimeout(this.#pollTimer);
      this.#pollTimer = null;
    }
  }

  async selectMission(id) {
    if (!id || id === this.#currentMissionId) return;
    this.#currentMissionId = id;
    localStorage.setItem('jl03-mission', id);
    this.#container.innerHTML = '';
    this.#eventsMap.set(id, { events: [], cursor: null });
    await this.#fetchAndDisplayMissionEvents(id, true);
    this.#schedulePoll();
  }

  async #loadMissions() {
    try {
      this.#missions = await api('/api/missions');
      this.#select.innerHTML = '';
      this.#missions.forEach((m) => {
        const opt = new Option(`${m.id} — ${m.goal}`, m.id);
        this.#select.add(opt);
      });
    } catch (e) {
      this.#container.innerHTML = `<p class="error">Impossible de charger les missions.</p>`;
    }
  }

  async #restoreSelection() {
    const saved = localStorage.getItem('jl03-mission');
    if (saved && this.#missions.some((m) => m.id === saved)) {
      this.#select.value = saved;
      await this.selectMission(saved);
      return;
    }
    // Sélectionner la mission la plus récente
    const last = this.#missions
      .sort((a, b) => new Date(b.updated) - new Date(a.updated))[0];
    if (last) {
      this.#select.value = last.id;
      await this.selectMission(last.id);
    }
  }

  async #fetchAndDisplayMissionEvents(missionId, fromZero = false) {
    const { cursor } = this.#eventsMap.get(missionId) || {};
    const after = fromZero ? '' : (cursor ?? '');
    try {
      const res = await api(`/api/v3/events?mission=${encodeURIComponent(missionId)}&after=${encodeURIComponent(after)}`);
      const { events, cursor: newCursor, has_more } = res;
      const existing = this.#eventsMap.get(missionId) || { events: [], cursor: null };
      const newEvents = [...existing.events, ...events];
      this.#eventsMap.set(missionId, { events: newEvents, cursor: newCursor });

      // Affichage progressif
      for (const event of events) {
        this.#appendEvent(event);
      }

      // Si pagination incomplète, continue avec la même requête
      if (has_more && newCursor) {
        await this.#fetchAndDisplayMissionEvents(missionId, false);
        return;
      }

      // Mise à jour de l’état
      this.#updateMissionState(missionId);
    } catch (e) {
      this.#container.innerHTML += `<p class="error">Reconnexion au laboratoire…</p>`;
      this.#scheduleRetry();
    }
  }

  async #schedulePoll() {
    if (!this.#polling) return;
    const missionId = this.#currentMissionId;
    if (!missionId) return;
    await this.#fetchAndDisplayMissionEvents(missionId, false);
    this.#pollTimer = setTimeout(() => this.#schedulePoll(), this.#pollInterval);
  }

  async #scheduleRetry() {
    if (!this.#polling) return;
    await new Promise((r) => setTimeout(r, 3000));
    const missionId = this.#currentMissionId;
    if (!missionId) return;
    await this.#fetchAndDisplayMissionEvents(missionId, false);
    this.#pollTimer = setTimeout(() => this.#schedulePoll(), this.#pollInterval);
  }

  #updateMissionState(missionId) {
    const mission = this.#missions.find((m) => m.id === missionId);
    if (!mission) return;
    const state = ['running', 'queued', 'publishing'].includes(mission.state) ? 'thinking' : 'listening';
    this.#onState(state);
  }

  #appendEvent(event) {
    const { id, created, actor, kind, tool, arguments: args, result, duration, invocation } = event;
    const section = document.createElement('section');
    section.dataset.eventId = id;

    // Date et auteur
    const header = document.createElement('header');
    const date = new Date(created).toLocaleString('fr-FR');
    const actorLabel = actor === 'Codex' ? 'Codex' : actor === 'JARVIS' ? 'JARVIS' : 'worker';
    header.innerHTML = `<time datetime="${created}">${date}</time> — <strong>${actorLabel}</strong>`;
    section.appendChild(header);

    // Titre français
    const kindLabel = this.#kindLabel(kind, tool);
    const title = document.createElement('h3');
    title.textContent = kindLabel;
    section.appendChild(title);

    // Commande
    if (args?.command) {
      const cmd = document.createElement('p');
      cmd.textContent = `> ${args.command}`;
      section.appendChild(cmd);
    }

    // Arguments complets
    if (args && Object.keys(args).length > 0) {
      const argsEl = document.createElement('pre');
      argsEl.textContent = JSON.stringify(args, null, 2);
      section.appendChild(argsEl);
    }

    // Résultat complet
    if (result) {
      const resEl = document.createElement('pre');
      resEl.textContent = JSON.stringify(result, null, 2);
      section.appendChild(resEl);
    }

    // stdout/stderr
    if (result?.stdout) {
      const stdoutEl = document.createElement('pre');
      stdoutEl.textContent = result.stdout;
      section.appendChild(stdoutEl);
    }
    if (result?.stderr) {
      const stderrEl = document.createElement('pre');
      stderrEl.textContent = result.stderr;
      section.appendChild(stderrEl);
    }

    // Durée
    if (duration !== undefined) {
      const durationEl = document.createElement('small');
      durationEl.textContent = `Durée : ${duration} ms`;
      section.appendChild(durationEl);
    }

    // Liens et médias
    if (result?.result?.path) {
      const path = result.result.path;
      const url = artifactURL(path);
      const link = document.createElement('a');
      link.href = url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.textContent = `Fichier produit : ${path}`;
      section.appendChild(link);
    }
    if (result?.wav_file) {
      const audio = document.createElement('audio');
      audio.controls = true;
      audio.src = artifactURL(result.wav_file);
      section.appendChild(audio);
    }
    // URLs GitHub détectées
    const githubRegex = /https:\/\/github\.com\/[^\s)]+/g;
    const githubMatches = (JSON.stringify(result) || '').match(githubRegex);
    if (githubMatches) {
      const dedup = [...new Set(githubMatches)];
      dedup.forEach((url) => {
        const link = document.createElement('a');
        link.href = url;
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        link.textContent = url;
        section.appendChild(link);
      });
    }

    // États spécifiques
    if (kind === 'loop_guard_blocked' || kind === 'loop_strategy_changed') {
      const alert = document.createElement('p');
      alert.style.fontWeight = 'bold';
      alert.style.color = '#c00';
      alert.textContent = 'BLOQUÉE — ANALYSE DOCUMENTÉE';
      section.appendChild(alert);
    }

    // Styles d’état
    const status = this.#classifyEvent(event);
    switch (status) {
      case 'error':
        section.style.borderLeft = '4px solid #c00';
        break;
      case 'warning':
        section.style.borderLeft = '4px solid #d98000';
        break;
      case 'success':
        section.style.borderLeft = '4px solid #0a0';
        break;
    }

    // Insertion à la fin
    this.#container.appendChild(section);
    this.#container.scrollTop = this.#container.scrollHeight;
  }

  #classifyEvent(event) {
    const { result } = event;
    if (!result) return 'neutral';
    if (result.error || result.exit_code !== undefined && result.exit_code !== 0) return 'error';
    if (result.warning) return 'warning';
    return 'success';
  }

  #kindLabel(kind, tool) {
    const map = {
      command_run: `Exécution de la commande : ${tool}`,
      file_read: `Lecture du fichier : ${tool}`,
      file_write: `Écriture du fichier : ${tool}`,
      loop_guard_blocked: 'Boucle bloquée — analyse documentée',
      loop_strategy_changed: 'Changement de stratégie de boucle',
      model_query: 'Interrogation du modèle',
      model_response: 'Réponse du modèle',
      tool_select: 'Sélection d’outil',
      artifact_publish: 'Publication d’artefact',
      mission_end: 'Mission terminée',
      mission_start: 'Mission lancée',
    };
    return map[kind] || `${kind} (${tool})`;
  }

  get diagnostics() {
    const missionId = this.#currentMissionId;
    const entry = this.#eventsMap.get(missionId) || { events: [], cursor: null };
    return {
      mission: missionId,
      cursor: entry.cursor,
      eventCount: entry.events.length,
      polling: this.#polling,
    };
  }
}

import { api } from './api.js';

/**
 * VoiceController – Gestion locale de la parole, transcription et synthèse.
 * Contrôle micro + TTS/STT, sans dépendance externe (hors API).
 * Aucun appel à /api/missions/interrupt : interruption locale seulement.
 */
export class VoiceController {
  #micStream;
  #micTracks = [];
  #mediaRecorder;
  #vadTimer;
  #rmsTimer;
  #audioContext;
  #analyser;
  #vadThreshold = 0.02;
  #minSpeechDuration = 400;
  #silenceDuration = 700;
  #maxSpeechDuration = 20000;
  #silenceTimer;
  #currentRecording;
  #lastSpeechTime = 0;
  #micEnabled = false;
  #ttsPlayer;
  #ttsEpoch = 0;
  #silenceStart = 0;
  #onTranscript;
  #onState;
  #onAudio;
  #onError;

  constructor({ onTranscript, onState, onAudio, onError }) {
    this.#onTranscript = onTranscript;
    this.#onState = onState;
    this.#onAudio = onAudio;
    this.#onError = onError;
  }

  get micEnabled() {
    return this.#micEnabled;
  }

  async #initAudioContext() {
    if (!this.#audioContext) {
      this.#audioContext = new (window.AudioContext || window.webkitAudioContext)();
      this.#analyser = this.#audioContext.createAnalyser();
      this.#analyser.fftSize = 512;
      this.#analyser.smoothingTimeConstant = 0.85;
    }
    if (this.#audioContext.state === 'suspended') {
      await this.#audioContext.resume();
    }
  }

  async startMic() {
    if (this.#micEnabled) return;

    try {
      await this.#initAudioContext();
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });
      this.#micStream = stream;
      this.#micTracks = Array.from(stream.getTracks());

      const mediaStream = new MediaStream(this.#micTracks);
      this.#mediaRecorder = new MediaRecorder(mediaStream, {
        mimeType: this.#getSupportedRecorderType(),
      });

      this.#setupVAD();
      this.#micEnabled = true;
    } catch (err) {
      this.#onError?.(new Error(`startMic: ${err.message}`));
      throw err;
    }
  }

  stopMic() {
    if (!this.#micEnabled) return;

    // Stopper les pistes possédées par cette instance
    this.#micTracks.forEach(track => track.stop?.());
    this.#micTracks = [];
    this.#micStream = null;
    this.#mediaRecorder?.stream?.getTracks().forEach(track => track.stop?.());
    this.#mediaRecorder = null;

    // Nettoyage timers
    if (this.#vadTimer) cancelAnimationFrame(this.#vadTimer);
    if (this.#rmsTimer) clearTimeout(this.#rmsTimer);
    if (this.#silenceTimer) clearTimeout(this.#silenceTimer);

    // Reset VAD
    this.#currentRecording = null;
    this.#lastSpeechTime = 0;
    this.#silenceStart = 0;
    this.#micEnabled = false;
  }

  #getSupportedRecorderType() {
    const candidates = [
      'audio/webm;codecs=opus',
      'audio/webm',
      'audio/mp4;codecs=mp4a',
    ];
    return candidates.find(MediaRecorder.isTypeSupported);
  }

  #setupVAD() {
    const onData = (e) => {
      const blob = e.data;
      if (!blob || blob.size === 0) return;

      this.#currentRecording = this.#currentRecording || new Uint8Array(0);

      // Fusionner les nouveaux données
      const buffer = new Uint8Array(this.#currentRecording.length + blob.size);
      buffer.set(this.#currentRecording);
      buffer.set(new Uint8Array(blob), this.#currentRecording.length);
      this.#currentRecording = buffer;

      // Analyse RMS
      this.#processAudioBlob(blob);
    };

    const onEnd = () => {
      if (this.#currentRecording?.length > 0) {
        this.#submitRecording();
      }
    };

    this.#mediaRecorder.ondataavailable = onData;
    this.#mediaRecorder.onstop = onEnd;
    this.#mediaRecorder.start(500);

    // Initialiser l’analyseur
    if (this.#micStream) {
      const source = this.#audioContext.createMediaStreamSource(this.#micStream);
      source.connect(this.#analyser);
      this.#rmsTimer = this.#processRMS();
    }
  }

  #processRMS() {
    const buffer = new Float32Array(this.#analyser.frequencyBinCount);

    const loop = () => {
      if (!this.#micEnabled || !this.#analyser) {
        this.#rmsTimer = null;
        return;
      }

      this.#analyser.getFloatTimeDomainData(buffer);

      let sum = 0;
      for (let i = 0; i < buffer.length; i++) {
        sum += buffer[i] * buffer[i];
      }
      const rms = Math.sqrt(sum / buffer.length);

      if (rms > this.#vadThreshold) {
        this.#lastSpeechTime = Date.now();
      }

      // Silence prolongé
      if (this.#lastSpeechTime > 0 && Date.now() - this.#lastSpeechTime > this.#silenceDuration) {
        if (!this.#silenceTimer) {
          this.#silenceTimer = setTimeout(() => {
            // Silence confirmé
            if (
              this.#mediaRecorder &&
              this.#mediaRecorder.state === 'recording'
            ) {
              this.#mediaRecorder.stop();
              this.#silenceTimer = null;
            }
          }, this.#silenceDuration);
        }
      }

      this.#vadTimer = requestAnimationFrame(loop);
    };

    this.#vadTimer = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(this.#vadTimer);
  }

  #processAudioBlob(blob) {
    // Pas d’analyse en temps réel ici : on délègue le RNS à la VAD.
  }

  #submitRecording() {
    if (!this.#currentRecording || this.#currentRecording.length === 0) return;

    const blob = new Blob([this.#currentRecording], { type: this.#mediaRecorder.mimeType });
    this.#currentRecording = null;

    // POST /api/stt
    (async () => {
      try {
        const res = await api('/stt', blob);
        if (res?.text) {
          this.#onTranscript?.(res.text);
        }
      } catch (err) {
        this.#onError?.(new Error(`STT failure: ${err.message}`));
      }
    })();
  }

  async speak(text) {
    if (typeof text !== 'string' || !text.trim()) return;

    this.#onState?.('thinking');

    try {
      const res = await api('/tts', { text });
      if (!(res instanceof Blob)) {
        throw new Error('TTS expected a Blob');
      }

      const url = URL.createObjectURL(res);
      const audio = new Audio(url);
      audio.preload = 'auto';
      audio.crossOrigin = 'anonymous';

      const playback = new Promise((resolve, reject) => {
        audio.onplay = () => {
          this.#onState?.('speaking');
        };
        audio.onended = () => {
          URL.revokeObjectURL(url);
          this.#onState?.('listening');
          resolve();
        };
        audio.onerror = () => {
          URL.revokeObjectURL(url);
          reject(new Error('Audio playback error'));
        };
        audio.onpause = () => {
          // Pas d'annulation : seulement un signal
        };
      });

      // Envoi à orbe
      this.#onAudio?.(audio);

      // Gestion de l’interruption (via speechEpoch)
      const currentEpoch = this.#ttsEpoch;
      try {
        await audio.play();
      } catch (err) {
        if (err.name === 'NotAllowedError' || err.name === 'AbortError') {
          throw new Error('Autoplay refusé : interaction utilisateur requise');
        }
        throw err;
      }

      // Vérifier l’epoch après le play : ne pas continuer si interrompu
      if (this.#ttsEpoch !== currentEpoch) {
        return;
      }

      // Attendre la fin (ou interruption)
      await playback;
    } catch (err) {
      this.#onError?.(err);
      this.#onState?.('listening');
    }
  }

  interruptAudio() {
    this.#ttsEpoch++;
    if (this.#ttsPlayer) {
      this.#ttsPlayer.pause();
      this.#ttsPlayer = null;
    }
  }

  // LiveKit – prototype23D, EXPLICITEMENT distinct du fil canonique
  #liveKitRoom = null;
  #liveKitClient = null;

  async connectLiveKit() {
    try {
      if (!window.LivekitClient) {
        throw new Error('LiveKit SDK non disponible');
      }

      // Récupérer le token
      const res = await api('/v3/livekit-token');
      if (!res?.url || !res?.token || !res?.room) {
        throw new Error('Réponse LiveKit invalide');
      }

      this.#liveKitClient = new window.LivekitClient();
      this.#liveKitRoom = new this.#liveKitClient.Room();
      this.#liveKitRoom.on(this.#liveKitClient.RoomEvent.TrackSubscribed, (track, publication, participant) => {
        if (track.kind === 'audio') {
          const element = track.createTrackElement();
          this.#onAudio?.(element);
        }
      });
      this.#liveKitRoom.on(this.#liveKitClient.RoomEvent.ActiveSpeakersChanged, (speakers) => {
        // Signaler l’état global si nécessaire
      });

      await this.#liveKitRoom.connect(res.url, res.token);
      await this.#liveKitRoom.setMicrophoneEnabled(true);
    } catch (err) {
      this.#onError?.(new Error(`LiveKit connect: ${err.message}`));
      throw err;
    }
  }

  disconnectLiveKit() {
    if (!this.#liveKitRoom) return;
    this.#liveKitRoom.disconnect();
    this.#liveKitRoom = null;
    this.#liveKitClient = null;
  }
}

/**
 * JL03 — telemetry.js
 * Render telemetry cards for launcher resources.
 * Exports: renderTelemetry(element, data)
 */

export function renderTelemetry(element, data) {
  if (!element || !data || !data.machines) return;

  element.innerHTML = '';
  element.style.display = 'flex';
  element.style.flexDirection = 'row';
  element.style.gap = '1rem';
  element.style.flexWrap = 'wrap';
  element.style.overflowX = 'auto';
  element.style.padding = '0.5rem';

  const now = Date.now();

  Object.entries(data.machines).forEach(([machineId, node]) => {
    const card = document.createElement('div');
    card.className = 'machine-card';
    card.style.cssText = `
      flex: 0 0 auto;
      min-width: 240px;
      background: #0f1112;
      border: 1px solid #00a8a8;
      border-radius: 4px;
      padding: 0.75rem;
      color: #e0f7f7;
      font-family: monospace;
    `;

    // Header
    const title = document.createElement('h3');
    const machineName = {
      'mac-mini': 'Mac mini',
      'dell-1': 'Dell1',
      'dell-2': 'Dell2',
    }[machineId] || machineId;
    title.textContent = machineName;
    title.style.cssText = 'margin: 0 0 0.5rem 0; font-size: 1rem; color: #00d9d9;';

    card.appendChild(title);

    // Availability
    const avail = node.available !== undefined ? node.available : false;
    const statusLine = document.createElement('div');
    statusLine.textContent = `Disponibilité : ${avail ? '✓' : '✗'}`;
    statusLine.style.cssText = 'font-weight: bold;';
    card.appendChild(statusLine);

    // CPU
    if (node.cpu_percent != null && Number.isFinite(node.cpu_percent)) {
      const cpuLine = document.createElement('div');
      cpuLine.textContent = `CPU : ${node.cpu_percent.toFixed(1)}%`;
      card.appendChild(cpuLine);
    }

    // RAM
    if (
      node.ram_used_mb != null &&
      Number.isFinite(node.ram_used_mb) &&
      node.ram_total_mb != null &&
      Number.isFinite(node.ram_total_mb)
    ) {
      const usedGio = (node.ram_used_mb / 1024).toFixed(1);
      const totalGio = (node.ram_total_mb / 1024).toFixed(1);
      const ramLine = document.createElement('div');
      ramLine.textContent = `RAM : ${usedGio}/${totalGio} Gio`;
      card.appendChild(ramLine);
    }

    // CPU Temperature
    if (node.cpu_temperature_c != null && Number.isFinite(node.cpu_temperature_c)) {
      const tempLine = document.createElement('div');
      tempLine.textContent = `Temp. CPU : ${node.cpu_temperature_c.toFixed(1)} °C`;
      card.appendChild(tempLine);
    } else {
      const tempLine = document.createElement('div');
      tempLine.textContent = 'Temp. CPU : non mesurée';
      card.appendChild(tempLine);
    }

    // Timestamp and age warning
    const tsLine = document.createElement('div');
    const sampledAt = node.sampled_at ? new Date(node.sampled_at) : null;
    const ageMs = sampledAt ? now - sampledAt.getTime() : null;
    const isOld = ageMs != null && ageMs > 30000;
    const timestampText = sampledAt ? sampledAt.toISOString() : 'inconnue';
    tsLine.textContent = sampledAt ? `Mesuré à ${timestampText.split('T')[1].slice(0,8)} ${isOld ? '(ancien)' : ''}` : 'Aucune date';
    tsLine.title = `Dernière mesure : ${timestampText}${isOld ? ' — données >30s' : ''}`;
    tsLine.style.cssText = isOld ? 'color: #ff9800;' : 'opacity: 0.8;';
    card.appendChild(tsLine);

    // GPU cards
    const gpus = Array.isArray(node.gpus) ? node.gpus : [];
    const hasGpuField = node.gpu && typeof node.gpu === 'object';
    const gpuFallback = hasGpuField && !gpus.length ? [node.gpu] : gpus;

    if (!gpuFallback.length) {
      const noGpu = document.createElement('div');
      noGpu.textContent = 'GPU : aucun détecté';
      noGpu.style.cssText = 'color: #888;';
      card.appendChild(noGpu);
    } else {
      gpuFallback.forEach((gpu, idx) => {
        const gpuSlot = document.createElement('div');
        gpuSlot.className = 'gpu-slot';
        gpuSlot.style.cssText = 'margin-top: 0.5rem; padding-left: 0.5rem; border-left: 1px solid #00a8a8; font-size: 0.9rem;';

        if (!node.available) {
          gpuSlot.textContent = `GPU${idx + 1} : indisponible`;
        } else {
          const name = gpu.name || `GPU ${idx}`;
          const util =
            gpu.utilization != null && Number.isFinite(gpu.utilization)
              ? `${gpu.utilization}%`
              : 'N/A';
          const temp =
            gpu.temperature != null && Number.isFinite(gpu.temperature)
              ? `${gpu.temperature} °C`
              : 'N/A';
          const vramUsedGio =
            gpu.vram_used_mb != null && Number.isFinite(gpu.vram_used_mb)
              ? (gpu.vram_used_mb / 1024).toFixed(1)
              : 'N/A';
          const vramTotalGio =
            gpu.vram_total_mb != null && Number.isFinite(gpu.vram_total_mb)
              ? (gpu.vram_total_mb / 1024).toFixed(1)
              : 'N/A';

          gpuSlot.textContent = `GPU${idx + 1} : ${name} | ${util} | VRAM : ${vramUsedGio}/${vramTotalGio} Gio | Temp : ${temp}`;
          if (gpu.name) {
            gpuSlot.title = `GPU${idx + 1} : ${gpu.name}`;
          }
        }

        card.appendChild(gpuSlot);
      });
    }

    // Fill remaining slots for Dell machines if needed
    if (machineId.startsWith('dell-') && gpuFallback.length === 1) {
      const fallbackSlot = document.createElement('div');
      fallbackSlot.className = 'gpu-slot';
      fallbackSlot.textContent = 'GPU2 : non détecté';
      fallbackSlot.style.cssText = 'color: #ff9800;';
      card.appendChild(fallbackSlot);
    }

    element.appendChild(card);
  });

  // Ensure a consistent gap for horizontal scroll if needed
  const filler = document.createElement('div');
  filler.style.cssText = 'flex: 1; min-width: 0;';
  element.appendChild(filler);
}

export class VoiceController {
  constructor({ onTranscript, onState, onAudio, onError }) {
    this.#onTranscript = onTranscript;
    this.#onState = onState;
    this.#onAudio = onAudio;
    this.#onError = onError;
    this.#micEnabled = false;
    this.#ttsPlayer = null;
    this.#ttsEpoch = 0;
    this.#recorder = null;
    this.#stream = null;
    this.#audioContext = null;
    this.#analyzer = null;
    this.#rmsRaf = null;
    this.#chunks = [];
    this.#hasSpeech = false;
    this.#lastSpeechMs = 0;
    this.#silenceTimer = null;
    this.#maxSegmentMs = 20_000;
    this.#silenceThreshold = 0.02;
    this.#silenceDurationForStop = 700;
  }

  #onTranscript = null;
  #onState = null;
  #onAudio = null;
  #onError = null;
  #micEnabled = false;
  #ttsPlayer = null;
  #ttsEpoch = 0;
  #recorder = null;
  #stream = null;
  #audioContext = null;
  #analyzer = null;
  #rmsRaf = null;
  #chunks = [];
  #hasSpeech = false;
  #lastSpeechMs = 0;
  #silenceTimer = null;
  #maxSegmentMs = 20_000;
  #silenceThreshold = 0.02;
  #silenceDurationForStop = 700;

  async #api(path, body, init = {}) {
    const headers = { ...init.headers, 'Content-Type': 'application/json' };
    if (body instanceof Blob) {
      headers['Content-Type'] = 'audio/wav';
    }
    const res = await fetch(`/api${path}`, { ...init, body, headers });
    if (!res.ok) throw new Error(`API error: ${res.status}`);
    return res;
  }

  async startMic() {
    if (this.#micEnabled) return;
    this.#micEnabled = true;
    this.#onState('listening');

    try {
      this.#stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          sampleRate: 16000,
        },
      });

      this.#audioContext = new AudioContext({ sampleRate: 16000 });
      const source = this.#audioContext.createMediaStreamSource(this.#stream);
      this.#analyzer = this.#audioContext.createAnalyser();
      this.#analyzer.fftSize = 128;
      source.connect(this.#analyzer);

      this.#chunks = [];
      this.#hasSpeech = false;
      this.#lastSpeechMs = 0;
      this.#recorder = new MediaRecorder(this.#stream, { mimeType: 'audio/webm;codecs=opus' });

      this.#recorder.ondataavailable = (e) => {
        if (e.data.size > 0) this.#chunks.push(e.data);
      };

      this.#recorder.onstop = async () => {
        if (!this.#chunks.length) return;
        const blob = new Blob(this.#chunks, { type: this.#recorder.mimeType || 'audio/webm' });
        try {
          const res = await this.#api('/stt', blob, { method: 'POST' });
          const json = await res.json();
          const text = json.text || '';
          this.#onTranscript?.(text);
        } catch (err) {
          this.#onError?.(err.message || 'STT failed');
        }
        this.#chunks = [];
        // Recreate recorder if mic still enabled
        if (this.#micEnabled) {
          this.#recorder = new MediaRecorder(this.#stream, { mimeType: 'audio/webm;codecs=opus' });
          this.#recorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.#chunks.push(e.data);
          };
          this.#recorder.onstop = async () => {
            if (!this.#chunks.length) return;
            const blob = new Blob(this.#chunks, { type: this.#recorder.mimeType || 'audio/webm' });
            try {
              const res = await this.#api('/stt', blob, { method: 'POST' });
              const json = await res.json();
              const text = json.text || '';
              this.#onTranscript?.(text);
            } catch (err) {
              this.#onError?.(err.message || 'STT failed');
            }
            this.#chunks = [];
          };
          this.#recorder.start(1000);
        }
      };

      this.#recorder.start(1000);

      this.#startVAD();
    } catch (err) {
      this.#micEnabled = false;
      this.#onError?.(err.message || 'Mic access failed');
    }
  }

  stopMic() {
    this.#micEnabled = false;
    this.#stopVAD();

    if (this.#recorder && this.#recorder.state !== 'inactive') {
      // Keep recorder ref to use in onstop
      const recorder = this.#recorder;
      recorder.onstop = async () => {
        // onstop is already bound above; do nothing extra here
      };
      recorder.stop();
    }

    if (this.#stream) {
      this.#stream.getTracks().forEach((t) => t.stop());
      this.#stream = null;
    }

    if (this.#audioContext) {
      await this.#audioContext.close();
      this.#audioContext = null;
      this.#analyzer = null;
    }

    clearTimeout(this.#silenceTimer);
    this.#silenceTimer = null;
  }

  async speak(text) {
    if (!this.#onAudio) {
      this.#onError?.('No audio output available');
      return;
    }
    this.#ttsEpoch++;
    const epoch = this.#ttsEpoch;
    this.#onState('thinking');
    try {
      const res = await this.#api('/tts', { text }, { method: 'POST' });
      if (epoch !== this.#ttsEpoch) return;
      const blob = await res.blob();
      if (!blob.size) throw new Error('Empty TTS blob');
      this.#onState('speaking');

      const audio = new Audio(URL.createObjectURL(blob));
      audio.onended = () => {
        if (this.#micEnabled) this.#onState('listening');
      };
      audio.onerror = () => {
        this.#onError?.('Autoplay blocked or audio error');
        this.#onState('listening');
      };
      this.#onAudio?.(audio);
      this.#ttsPlayer = audio;
      await audio.play();
      if (epoch !== this.#ttsEpoch) {
        await audio.pause();
        URL.revokeObjectURL(audio.src);
        return;
      }
      URL.revokeObjectURL(audio.src);
      this.#onState('listening');
    } catch (err) {
      this.#onError?.(err.message || 'TTS failed');
      this.#onState('listening');
    }
  }

  interruptAudio() {
    if (this.#ttsPlayer) {
      this.#ttsPlayer.pause();
      this.#ttsEpoch++;
      this.#ttsPlayer = null;
    }
  }

  #startVAD() {
    const data = new Float32Array(this.#analyzer.fftSize);
    const now = performance.now();
    const checkSpeech = () => {
      if (!this.#micEnabled) return;
      this.#analyzer.getFloatRMSData?.(data) || this.#analyzer.getFloatTimeDomainData?.(data);
      let rms = 0;
      for (let i = 0; i < data.length; i++) rms += data[i] * data[i];
      rms = Math.sqrt(rms / data.length) || 0;

      const t = performance.now();
      if (rms > this.#silenceThreshold) {
        this.#lastSpeechMs = t;
        this.#hasSpeech = true;
        // interrupt TTS on speech
        if (this.#ttsPlayer && !this.#ttsPlayer.paused) {
          this.interruptAudio();
        }
        clearTimeout(this.#silenceTimer);
        this.#silenceTimer = setTimeout(() => {
          if (this.#recorder && this.#recorder.state === 'recording') {
            this.#recorder.stop();
          }
        }, this.#silenceDurationForStop);
      }
      this.#rmsRaf = requestAnimationFrame(checkSpeech);
    };
    this.#rmsRaf = requestAnimationFrame(checkSpeech);
  }

  #stopVAD() {
    if (this.#rmsRaf) cancelAnimationFrame(this.#rmsRaf);
    this.#rmsRaf = null;
    clearTimeout(this.#silenceTimer);
    this.#silenceTimer = null;
  }

  get micEnabled() {
    return this.#micEnabled;
  }
}

import { api, artifactURL } from './api.js';

export class MissionConsole {
  constructor({ container, select, onState, onActivity }) {
    this.container = container;
    this.select = select;
    this.onState = onState;
    this.onActivity = onActivity;
    this.currentMissionId = null;
    this.missions = new Map();
    this.cursor = {};
    this.timer = null;
    this.inFlight = false;
    this.autoscroll = true;
    this.recentlyScrolledUp = false;
    this.pollingInterval = 2000;
  }

  start() {
    this.select.addEventListener('change', () => this.selectMission(this.select.value));
    this.loadMissions();
    this.poll();
  }

  stop() {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
  }

  async loadMissions() {
    try {
      const response = await api.get('/api/missions');
      const missions = await response.json();
      const currentId = this.select.value;
      this.select.innerHTML = '';
      missions.forEach(mission => {
        const option = document.createElement('option');
        option.value = mission.id;
        option.textContent = mission.goal?.split('\n')[0] || `Mission ${mission.id}`;
        this.select.appendChild(option);
      });
      if (currentId && this.select.querySelector(`option[value="${currentId}"]`)) {
        this.select.value = currentId;
        this.selectMission(currentId);
      } else if (this.select.options.length > 0) {
        this.select.selectedIndex = 0;
        this.selectMission(this.select.value);
      }
    } catch (err) {
      console.error('Erreur chargement missions:', err);
    }
  }

  async selectMission(id) {
    this.currentMissionId = id;
    this.container.innerHTML = '';
    this.recentlyScrolledUp = false;
    if (this.autoscrollButton) {
      this.autoscrollButton.remove();
      this.autoscrollButton = null;
    }

    const data = this.missions.get(id);
    if (data && data.events) {
      this.cursor[id] = data.cursor;
      this.renderEvents(data.events);
    } else {
      this.cursor[id] = 0;
      await this.loadEvents(id, 0);
    }

    if (this.timer === null) {
      this.poll();
    }
  }

  async poll() {
    if (this.inFlight) return;
    if (!this.currentMissionId) {
      this.timer = setTimeout(() => this.poll(), this.pollingInterval);
      return;
    }

    this.inFlight = true;
    try {
      await this.loadEvents(this.currentMissionId, this.cursor[this.currentMissionId] || 0);
      await this.loadMissions();
      this.renewMissionState();
    } catch (err) {
      console.error('Erreur polling:', err);
    } finally {
      this.inFlight = false;
      this.timer = setTimeout(() => this.poll(), this.pollingInterval);
    }
  }

  async loadEvents(missionId, after) {
    const url = `/api/v3/events?mission=${missionId}&after=${after}`;
    try {
      const response = await api.get(url);
      const data = await response.json();

      if (!Array.isArray(data.events) || data.events.length === 0) {
        return;
      }

      const events = data.events;

      if (events.length > 0 && !this.missions.has(missionId)) {
        this.missions.set(missionId, { events: [], cursor: 0 });
      }

      const missionData = this.missions.get(missionId);
      if (after === 0) {
        missionData.events = events;
      } else {
        missionData.events = missionData.events.concat(events);
      }
      missionData.cursor = data.cursor;

      if (this.currentMissionId === missionId) {
        this.renderEvents(events, /* prepend */ after !== 0);
        this.renewMissionState();
      }

      if (data.has_more && data.cursor !== after) {
        await this.loadEvents(missionId, data.cursor);
      } else if (data.cursor === after) {
        console.warn(`Polling bloqué : cursor non avancé (${data.cursor}) pour mission ${missionId}`);
      }
    } catch (err) {
      const msg = document.createElement('div');
      msg.className = 'poll-error';
      msg.style.color = 'red';
      msg.textContent = `Erreur serveur : ${err.message}`;
      this.container.appendChild(msg);
    }
  }

  renewMissionState() {
    if (!this.currentMissionId) return;
    const missionData = this.missions.get(this.currentMissionId);
    if (!missionData) return;

    const lastEvent = [...missionData.events].reverse().find(e => e.kind === 'state_changed');
    if (!lastEvent) return;

    const state = lastEvent.arguments?.state;
    this.onState(state === 'running' || state === 'queued' || state === 'publishing' ? 'thinking' : 'listening');
  }

  renderEvents(events, prepend = false) {
    const frag = document.createDocumentFragment();
    const bottom = this.container.scrollHeight - this.container.scrollTop - this.container.clientHeight;

    for (const event of events) {
      const el = document.createElement('div');
      el.className = 'event';
      el.dataset.id = event.id;

      // Horodatage correct (secondes → milliseconds)
      const date = new Date(event.created * 1000);
      el.appendChild(document.createElement('time')).textContent = date.toISOString().replace('T',' ').split('.')[0];

      // Acteur exact
      el.appendChild(document.createElement('strong')).textContent = ` ${event.actor} —`;

      // Titre en français selon kind
      el.appendChild(document.createElement('span')).textContent = ` ${this.humanKind(event.kind)}`;

      // Arguments
      if (event.arguments && typeof event.arguments === 'object' && Object.keys(event.arguments).length > 0) {
        const details = document.createElement('details');
        const summary = document.createElement('summary');
        summary.textContent = 'Arguments';
        details.appendChild(summary);
        const pre = document.createElement('pre');
        pre.textContent = JSON.stringify(event.arguments, null, 2);
        details.appendChild(pre);
        el.appendChild(details);
      }

      // Résultat
      if (event.result && (event.result.stdout || event.result.stderr || event.result.result)) {
        const res = event.result;
        const resultDiv = document.createElement('div');
        resultDiv.className = 'result';

        // Déterminer le niveau de succès
        let status = 'neutral';
        if (res.ok === true || res.status === 'PASS') status = 'success';
        else if (res.ok === false || res.status === 'FAIL') status = 'error';
        else if (['INSUFFICIENT', 'PARTIAL'].includes(res.status || '')) status = 'warning';

        const statusSpan = document.createElement('span');
        statusSpan.className = `status ${status}`;
        statusSpan.textContent = status.toUpperCase();
        resultDiv.appendChild(statusSpan);

        if (res.path && res.path.endsWith('.wav')) {
          const a = document.createElement('a');
          a.href = artifactURL(res.path);
          a.target = '_blank';
          a.textContent = 'Fichier WAV';
          resultDiv.appendChild(a);
          const br = document.createElement('br');
          const player = document.createElement('audio');
          player.controls = true;
          player.src = artifactURL(res.path);
          resultDiv.appendChild(player);
        }

        if (res.result && typeof res.result.stdout === 'string' && res.result.stdout.length > 0) {
          const stdOut = document.createElement('div');
          stdOut.className = 'stdout';
          const stdOutPre = document.createElement('pre');
          stdOutPre.textContent = res.result.stdout;
          stdOut.appendChild(stdOutPre);
          resultDiv.appendChild(stdOut);
        }
        if (res.result && typeof res.result.stderr === 'string' && res.result.stderr.length > 0) {
          const stdErr = document.createElement('div');
          stdErr.className = 'stderr';
          const stdErrPre = document.createElement('pre');
          stdErrPre.textContent = res.result.stderr;
          stdErr.appendChild(stdErrPre);
          resultDiv.appendChild(stdErr);
        }

        if (Object.keys(res).some(k => k !== 'stdout' && k !== 'stderr' && k !== 'path' && k !== 'ok' && k !== 'status')) {
          const other = document.createElement('pre');
          other.textContent = JSON.stringify(res, Object.keys(res).filter(k => !['stdout','stderr','path','ok','status'].includes(k)), 2);
          resultDiv.appendChild(other);
        }

        el.appendChild(resultDiv);
      }

      if (event.duration !== undefined && event.duration !== null) {
        const durationSpan = document.createElement('small');
        durationSpan.textContent = ` (${event.duration}s)`;
        el.appendChild(durationSpan);
      }

      if (prepend) {
        this.container.insertBefore(el, this.container.firstChild);
      } else {
        frag.appendChild(el);
      }
    }

    if (frag.children.length > 0) {
      this.container.appendChild(frag);
    }

    // Scroll intelligente
    if (this.autoscroll) {
      this.container.scrollTop = this.container.scrollHeight;
    } else if (!this.autoscrollButton && this.recentlyScrolledUp) {
      this.createAutoscrollButton();
    } else if (this.autoscrollButton && this.autoscroll) {
      this.autoscrollButton.remove();
      this.autoscrollButton = null;
    }

    // Mise à jour de la distance au bas de page
    this.recentlyScrolledUp = (bottom < 20);
  }

  createAutoscrollButton() {
    const btn = document.createElement('button');
    btn.textContent = 'Revenir au direct';
    btn.style.position = 'fixed';
    btn.style.bottom = '1rem';
    btn.style.right = '1rem';
    btn.className = 'btn';
    btn.onclick = () => {
      this.autoscroll = true;
      this.container.scrollTop = this.container.scrollHeight;
      btn.remove();
      this.autoscrollButton = null;
    };
    document.body.appendChild(btn);
    this.autoscrollButton = btn;
  }

  humanKind(kind) {
    const map = {
      'mission_created': 'Mission créée',
      'tool_started': 'Outil lancé',
      'tool_finished': 'Outil terminé',
      'operator_tool_started': 'Outil humain lancé',
      'operator_tool_finished': 'Outil humain terminé',
      'coordinator_update': 'Mise à jour du coordinateur',
      'compute_route_observed': 'Route calculée observée',
      'state_changed': 'Changement d’état',
      'loop_guard_blocked': 'Blocage par gardien de boucle',
      'loop_strategy_changed': 'Changement de stratégie de boucle',
      'manual_operator_reception': 'Réception opérateur manuelle'
    };
    return map[kind] || kind;
  }
}

import { api, artifactURL } from './api.js';

export class MissionConsole {
  constructor({ container, select, onState, onActivity }) {
    this.container = container;
    this.select = select;
    this.onState = onState;
    this.onActivity = onActivity;
    this.pollTimer = null;
    this.inFlight = false;
    this.missions = new Map(); // { events, cursor, id }
    this.autoscroll = true;
    this.currentMissionId = null;
    this.scrollButton = null;
  }

  async start() {
    if (this.pollTimer) return; // évite le double lancement
    await this.#schedulePoll(0);
  }

  stop() {
    if (this.pollTimer) {
      clearTimeout(this.pollTimer);
      this.pollTimer = null;
    }
  }

  async selectMission(id) {
    if (!id) {
      this.currentMissionId = null;
      this.container.innerHTML = '';
      return;
    }
    this.currentMissionId = id;
    const stored = this.missions.get(id);
    if (stored) {
      this.#renderMission(stored.events, stored.cursor);
      await this.#schedulePoll(0);
    } else {
      this.missions.set(id, { events: [], cursor: 0 });
      this.#renderMission([], 0);
      await this.#schedulePoll(0);
    }
  }

  async #schedulePoll(delay = 0) {
    if (this.pollTimer) return;
    this.pollTimer = setTimeout(async () => {
      this.pollTimer = null;
      if (this.inFlight || !this.currentMissionId) return;
      try {
        this.inFlight = true;
        const { events, cursor } = this.missions.get(this.currentMissionId) || { events: [], cursor: 0 };
        const url = `/api/v3/events?mission=${encodeURIComponent(this.currentMissionId)}&after=${cursor ?? 0}`;
        const res = await fetch(url);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (!Array.isArray(data.events)) throw new Error('réponse invalide');
        // Avance le curseur uniquement si des événements reçus
        const newEvents = data.events || [];
        if (newEvents.length > 0 && data.cursor != null) {
          // S'assurer que le curseur avance (sinon bloqué)
          if (Number(data.cursor) <= cursor) {
            console.error('Blocage de cursor :', cursor, '→', data.cursor);
            this.#addStatusMessage('Blocage de cursor détecté — arrêt du flux', 'warning');
            this.inFlight = false;
            return;
          }
        }
        const nextCursor = data.cursor ?? cursor;
        const updated = [...events, ...newEvents];
        this.missions.set(this.currentMissionId, { events: updated, cursor: nextCursor });
        this.#renderMission(updated, nextCursor);
        // Récupérer l'état de la mission
        const mRes = await fetch('/api/missions');
        if (mRes.ok) {
          const missions = await mRes.json();
          const active = missions.find(m => m.id === this.currentMissionId);
          if (active) {
            const state = ['running', 'queued', 'publishing'].includes(active.state) ? 'thinking' : 'listening';
            this.onState(state);
            this.onActivity('ready');
          }
        }
        // Suivi has_more
        if (data.has_more && newEvents.length === 0) {
          // Page vide mais has_more=true → problème réel, éviter boucle
          this.#addStatusMessage('Server a has_more mais aucun événement réel', 'error');
        } else if (data.has_more && newEvents.length > 0) {
          // Boucle immédiate pour les pages suivantes
          this.#schedulePoll(0);
        }
      } catch (err) {
        console.error('Polling error:', err);
        this.#addStatusMessage(`Erreur réseau : ${err.message}`, 'error');
        // Pas de stop de la mission, ni vidage de missions Map
        this.inFlight = false;
        // Retry avec délai (ne crée pas de nouvelle boucle si déjà un timer en cours)
        if (!this.pollTimer) {
          this.pollTimer = setTimeout(() => this.#schedulePoll(5000), 5000);
        }
      } finally {
        this.inFlight = false;
      }
    }, delay);
  }

  #renderMission(events, cursor) {
    if (!this.container) return;
    this.container.innerHTML = '';
    this.scrollButton = document.createElement('button');
    this.scrollButton.textContent = ' ↵ Revenir au direct';
    this.scrollButton.style.position = 'fixed';
    this.scrollButton.style.bottom = '16px';
    this.scrollButton.style.right = '16px';
    this.scrollButton.style.zIndex = '1000';
    this.scrollButton.style.display = 'none';
    this.scrollButton.onclick = () => {
      this.container.scrollTop = this.container.scrollHeight;
      this.autoscroll = true;
      this.scrollButton.style.display = 'none';
    };
    document.body.appendChild(this.scrollButton);
    events.forEach(ev => this.#renderEvent(ev));
  }

  #addStatusMessage(text, kind = 'info') {
    const msg = document.createElement('div');
    msg.className = `msg msg-${kind}`;
    msg.textContent = text;
    this.container.appendChild(msg);
    this.#maybeScroll();
  }

  #renderEvent(ev) {
    const { id, created, actor, kind, tool, arguments: args, result, duration, invocation } = ev;

    const section = document.createElement('section');
    section.dataset.id = id;
    section.style.border = '1px solid #ccc';
    section.style.padding = '8px';
    section.style.marginBottom = '8px';

    const header = document.createElement('header');
    header.style.display = 'flex';
    header.style.gap = '8px';
    header.style.fontWeight = 'bold';

    const ts = document.createElement('time');
    ts.textContent = new Date(created * 1000).toISOString().replace('T', ' ').split('.')[0];
    header.appendChild(ts);

    const kindSpan = document.createElement('span');
    kindSpan.style.textTransform = 'capitalize';
    kindSpan.textContent = this.#kindLabel(kind);
    header.appendChild(kindSpan);

    const actorSpan = document.createElement('span');
    actorSpan.style.color = '#666';
    actorSpan.textContent = actor ?? 'unknown';
    header.appendChild(actorSpan);

    section.appendChild(header);

    const body = document.createElement('div');
    body.style.marginTop = '4px';

    // Arguments
    if (args) {
      const argsPre = document.createElement('pre');
      argsPre.style.fontSize = '0.9em';
      argsPre.style.whiteSpace = 'pre-wrap';
      argsPre.style.wordBreak = 'break-all';
      argsPre.style.margin = '4px 0';
      argsPre.textContent = JSON.stringify(args, null, 2);
      body.appendChild(argsPre);
    }

    // Résultat
    const resDiv = document.createElement('div');
    const statusLabel = this.#statusLabel(result);
    const statusSpan = document.createElement('span');
    statusSpan.textContent = `(${statusLabel})`;
    statusSpan.style.color = this.#statusColor(result);
    resDiv.appendChild(statusSpan);

    if (result?.stdout) {
      const stdPre = document.createElement('pre');
      stdPre.style.fontSize = '0.85em';
      stdPre.style.whiteSpace = 'pre-wrap';
      stdPre.style.wordBreak = 'break-all';
      stdPre.style.margin = '4px 0';
      stdPre.textContent = result.stdout;
      resDiv.appendChild(stdPre);
    }
    if (result?.stderr) {
      const stdErrPre = document.createElement('pre');
      stdErrPre.style.fontSize = '0.85em';
      stdErrPre.style.whiteSpace = 'pre-wrap';
      stdErrPre.style.wordBreak = 'break-all';
      stdErrPre.style.margin = '4px 0';
      stdErrPre.textContent = result.stderr;
      resDiv.appendChild(stdErrPre);
    }
    if (result?.result?.stdout) {
      const stdPre = document.createElement('pre');
      stdPre.style.fontSize = '0.85em';
      stdPre.style.whiteSpace = 'pre-wrap';
      stdPre.style.wordBreak = 'break-all';
      stdPre.style.margin = '4px 0';
      stdPre.textContent = result.result.stdout;
      resDiv.appendChild(stdPre);
    }
    if (result?.result?.stderr) {
      const stdErrPre = document.createElement('pre');
      stdErrPre.style.fontSize = '0.85em';
      stdErrPre.style.whiteSpace = 'pre-wrap';
      stdErrPre.style.wordBreak = 'break-all';
      stdErrPre.style.margin = '4px 0';
      stdErrPre.textContent = result.result.stderr;
      resDiv.appendChild(stdErrPre);
    }
    if (result?.path && result.path.endsWith('.wav')) {
      const wavUrl = artifactURL(result.path);
      const a = document.createElement('a');
      a.href = wavUrl;
      a.textContent = ' WAV';
      resDiv.appendChild(a);
      const audio = document.createElement('audio');
      audio.controls = true;
      audio.src = wavUrl;
      resDiv.appendChild(audio);
    }
    if (result?.github) {
      const ghUrl = result.github;
      const ghLink = document.createElement('a');
      ghLink.href = ghUrl;
      ghLink.textContent = ' GitHub';
      ghLink.target = '_blank';
      resDiv.appendChild(ghLink);
    }
    if (duration != null && typeof duration === 'number') {
      const durSpan = document.createElement('span');
      durSpan.textContent = ` • ${duration.toFixed(3)}s`;
      resDiv.appendChild(durSpan);
    }
    body.appendChild(resDiv);

    section.appendChild(body);
    this.container.appendChild(section);
    this.#maybeScroll();
  }

  #maybeScroll() {
    if (this.autoscroll && this.container) {
      this.container.scrollTop = this.container.scrollHeight;
      this.scrollButton.style.display = 'none';
    } else if (this.container) {
      const threshold = 150;
      const atBottom = this.container.scrollHeight - this.container.scrollTop - this.container.clientHeight < threshold;
      if (!atBottom) {
        this.scrollButton.style.display = 'inline-block';
      }
    }
  }

  #kindLabel(kind) {
    const map = {
      mission_created: 'Mission créée',
      tool_started: 'Outil lancé',
      tool_finished: 'Outil terminé',
      operator_tool_started: 'Outil opérateur lancé',
      operator_tool_finished: 'Outil opérateur terminé',
      coordinator_update: 'Mise à jour协调',
      compute_route_observed: 'Route calculée',
      state_changed: 'Changement d’état',
      loop_guard_blocked: 'Blocage du garde',
      loop_strategy_changed: 'Changement de stratégie',
      manual_operator_reception: 'Réception opérateur manuel'
    };
    return map[kind] ?? kind;
  }

  #statusLabel(result) {
    if (!result) return 'sans résultat';
    if (result.ok === true) return 'Succès';
    if (result.ok === false) return 'Erreur';
    if (result.status === 'PASS') return 'Succès';
    if (result.status === 'FAIL') return 'Erreur';
    if (result.status === 'INSUFFICIENT' || result.status === 'PARTIAL') return 'Alerte';
    return 'Neutre';
  }

  #statusColor(result) {
    if (!result) return '#333';
    if (result.ok === true || result.status === 'PASS') return 'green';
    if (result.ok === false || result.status === 'FAIL') return 'red';
    if (result.status === 'INSUFFICIENT' || result.status === 'PARTIAL') return 'orange';
    return '#666';
  }
}

// console.js — Console minimaliste pour missions JL03
// Pas de framework, pas de données privées, pas de boucle infinie

import { api, artifactURL } from './api.js';

export class MissionConsole {
  constructor({ container, select, onState, onActivity }) {
    this.container = container;
    this.select = select;
    this.onState = onState;
    this.onActivity = onActivity;
    this.cache = new Map();
    this.id = null;
    this.running = false;
    this.busy = false;
    this.follow = true;
    this.timer = null;

    // Bouton Revenir au direct — créé une seule fois
    this.backButton = document.createElement('button');
    this.backButton.textContent = 'Revenir au direct';
    this.backButton.style.display = 'none'; // visible seulement si scroll manuel
    this.backButton.onclick = () => {
      this.follow = true;
      this.backButton.style.display = 'none';
      this.container.scrollTop = this.container.scrollHeight;
    };

    // Gestion des événements
    this.select.onchange = () => this.selectMission(Number(this.select.value));
    this.container.onscroll = () => {
      const atBottom = this.container.scrollHeight - this.container.scrollTop - this.container.clientHeight < 20;
      this.follow = atBottom;
      this.backButton.style.display = this.follow ? 'none' : 'inline-block';
    };

    // Intégration visuelle
    this.container.appendChild(this.backButton);
  }

  start() {
    this.running = true;
    this.poll();
  }

  stop() {
    this.running = false;
    clearTimeout(this.timer);
  }

  async poll() {
    if (this.busy || !this.running) return;

    this.busy = true;
    try {
      // 1. Charger la liste des missions (GET /api/missions)
      const missions = await api.get('/api/missions');
      if (!Array.isArray(missions) || missions.length === 0) {
        this.onActivity('Aucune mission disponible');
        return;
      }

      // Mise à jour du select (préservation du choix actuel)
      const currentId = this.id;
      const options = Array.from(this.select.options).map(o => o.value);
      const hasCurrent = options.includes(String(currentId));

      this.select.innerHTML = '';
      missions.forEach(m => {
        const option = document.createElement('option');
        option.value = m.id;
        option.textContent = `[${m.id}] ${m.name || 'Mission sans nom'}`;
        this.select.appendChild(option);
      });

      //Choix initial ou préservation
      if (!this.id || !hasCurrent) {
        const savedId = localStorage.getItem('jl03-mission');
        const validId = missions.find(m => m.id === Number(savedId)) ? Number(savedId) : missions[0].id;
        this.selectMission(validId);
      }

      // 2. Poller les événements de la mission sélectionnée
      await this._pollMissionEvents(this.id);

    } catch (err) {
      console.error('poll error:', err);
      this.onActivity('Erreur de synchronisation');
    } finally {
      this.busy = false;
    }

    // Une seule invocation du timer si running
    if (this.running) {
      this.timer = setTimeout(() => this.poll(), 2000);
    }
  }

  async _pollMissionEvents(id) {
    let cursor = this.cache.has(id) ? this.cache.get(id).cursor : 0;
    let hasMore = true;
    const loopGuard = new Set(); // pour éviter les boucles infinies

    while (hasMore && this.id === id) {
      const key = `${id}:${cursor}`;
      if (loopGuard.has(key)) break;
      loopGuard.add(key);

      try {
        const res = await api.get(`/api/v3/events?mission=${id}&after=${cursor}`);
        const { events, cursor: newCursor, has_more } = res;

        if (newCursor === cursor && events.length > 0) {
          // Boucle détectée (cursor bloqué, mais événements en double)
          this.onActivity('Alerte : curseur bloqué (boucle détectée)');
          break;
        }

        const cached = this.cache.get(id) || { events: [], cursor: 0 };
        const seen = new Set(cached.events.map(e => e.id));
        const newEvents = events.filter(e => !seen.has(e.id));
        this.cache.set(id, { events: [...cached.events, ...newEvents], cursor: newCursor });

        for (const ev of newEvents) {
          this._renderEvent(ev);
        }

        cursor = newCursor;
        hasMore = has_more;

      } catch (err) {
        console.error(`_pollMissionEvents error (id=${id}, cursor=${cursor}):`, err);
        this.onActivity(`Erreur lecture événements mission ${id}`);
        break;
      }
    }
  }

  selectMission(id) {
    if (typeof id !== 'number' || isNaN(id)) return;
    this.id = id;
    localStorage.setItem('jl03-mission', id);

    // Vider DOM une fois au changement de mission
    this.container.innerHTML = '';
    this.container.appendChild(this.backButton);

    // Restaurer les événements en cache
    const cached = this.cache.get(id);
    if (cached && Array.isArray(cached.events)) {
      for (const ev of cached.events) {
        this._renderEvent(ev);
      }
      // Remettre cursor à jour
      this.cache.set(id, { events: cached.events, cursor: cached.cursor });
    }

    // Forcer update du select
    this.select.value = String(id);
    // Lancer immédiatement un poll pour aller au-delà du cache
    this.poll();
  }

  _renderEvent(ev) {
    if (!ev || !ev.id) return;

    const { created, actor, kind, tool, arguments: args, result, duration } = ev;

    // Création de l'élément racine
    const block = document.createElement('div');
    block.className = 'jl03-event';
    block.style.border = '1px solid #ccc';
    block.style.padding = '0.5rem';
    block.style.marginTop = '0.5rem';

    // 1. Entête : acteur + date + label
    const header = document.createElement('div');
    header.style.fontWeight = 'bold';
    header.style.marginBottom = '0.5rem';

    const date = new Date(created * 1000).toLocaleString('fr-FR', { dateStyle: 'medium', timeStyle: 'medium' });
    const label = this._getEventLabel(kind, tool, actor, result);
    header.textContent = `${actor} — ${date} — ${label}`;

    block.appendChild(header);

    // 2. Arguments (complets, JSON, dans <pre>)
    if (args) {
      const argsPre = document.createElement('pre');
      argsPre.style.background = '#f5f5f5';
      argsPre.style.padding = '0.5rem';
      argsPre.style.whiteSpace = 'pre-wrap';
      argsPre.style.wordBreak = 'break-word';
      argsPre.textContent = JSON.stringify(args, null, 2);
      block.appendChild(argsPre);
    }

    // 3. Résultat
    if (result) {
      const resDiv = document.createElement('div');
      resDiv.style.marginTop = '0.5rem';

      // Statut visuel
      let statusClass = '';
      let statusText = '';
      if (result.ok === true || (typeof result === 'string' && result.toUpperCase() === 'PASS')) {
        statusClass = 'jl03-pass';
        statusText = '✓';
      } else if (result.ok === false || (typeof result === 'string' && result.toUpperCase() === 'FAIL')) {
        statusClass = 'jl03-fail';
        statusText = '✗';
      } else if (typeof result === 'string' && result.toUpperCase() === 'PARTIAL' ||
                 typeof result === 'string' && result.toUpperCase() === 'INSUFFICIENT') {
        statusClass = 'jl03-partial';
        statusText = '?';
      } else {
        statusClass = 'jl03-neutral';
        statusText = '—';
      }

      // Durée
      let durationText = '';
      if (duration && typeof duration === 'number') {
        durationText = ` (${duration.toFixed(3)} s)`;
      }

      const status = document.createElement('span');
      status.textContent = statusText;
      status.className = statusClass;
      resDiv.appendChild(status);

      const resultPre = document.createElement('pre');
      resultPre.style.background = '#fcfcfc';
      resultPre.style.padding = '0.5rem';
      resultPre.style.whiteSpace = 'pre-wrap';
      resultPre.style.wordBreak = 'break-word';

      // Si result.result.path est un chemin sous /var/lib/jarvis/projects...
      if (result && result.result && typeof result.result.path === 'string') {
        const path = result.result.path;
        const isArtifact = path.startsWith('/var/lib/jarvis/projects/');
        if (isArtifact) {
          // Créer un lien vers l’artifact + éventuellement lecteur audio WAV
          const artifactLink = document.createElement('a');
          artifactLink.href = artifactURL(path);
          artifactLink.target = '_blank';
          artifactLink.textContent = 'artifact';
          artifactLink.style.textDecoration = 'underline';
          artifactLink.style.color = 'blue';

          const artifactText = document.createTextNode(` → ${path} (`);
          resultPre.appendChild(artifactText);
          resultPre.appendChild(artifactLink);

          if (path.toLowerCase().endsWith('.wav')) {
            const audio = document.createElement('audio');
            audio.src = artifactURL(path);
            audio.controls = true;
            audio.style.marginLeft = '0.5rem';
            resultPre.appendChild(document.createTextNode(' '));
            resultPre.appendChild(audio);
          }

          resultPre.appendChild(document.createTextNode(')'));
        } else {
          resultPre.textContent = path;
        }
      } else {
        resultPre.textContent = JSON.stringify(result, null, 2);
      }

      resDiv.appendChild(resultPre);
      block.appendChild(resDiv);
    }

    // 4. stdout/stderr (si présents dans result ou result.result)
    const stdout = (result && result.stdout) || (result && result.result && result.result.stdout);
    const stderr = (result && result.stderr) || (result && result.result && result.result.stderr);

    if (stdout) {
      const outPre = document.createElement('pre');
      outPre.style.background = '#e8f5e9';
      outPre.style.padding = '0.5rem';
      outPre.style.whiteSpace = 'pre-wrap';
      outPre.style.wordBreak = 'break-word';
      outPre.textContent = stdout;
      block.appendChild(outPre);
    }

    if (stderr) {
      const errPre = document.createElement('pre');
      errPre.style.background = '#ffebee';
      errPre.style.padding = '0.5rem';
      errPre.style.whiteSpace = 'pre-wrap';
      errPre.style.wordBreak = 'break-word';
      errPre.textContent = stderr;
      block.appendChild(errPre);
    }

    // 5. loop_guard_blocked visible
    if (ev.kind === 'guard' && ev.tool === 'loop_guard') {
      const blocked = document.createElement('div');
      blocked.textContent = 'BLOQUÉE — ANALYSE DOCUMENTÉE';
      blocked.style.color = '#b71c1c';
      blocked.style.fontWeight = 'bold';
      block.appendChild(blocked);
    }

    // Ajout au DOM
    this.container.appendChild(block);
    if (this.follow) {
      this.container.scrollTop = this.container.scrollHeight;
    }
  }

  _getEventLabel(kind, tool, actor, result) {
    // Traduction humaine, contextuelle
    const kindMap = {
      'think': 'Réflexion',
      'plan': 'Planification',
      'act': 'Action',
      'listen': 'Écoute',
      'poll': 'Polling',
      'guard': 'Sécurité',
      'publish': 'Publication',
      'queue': 'Mise en file'
    };
    const toolMap = {
      'model': 'Modèle',
      'code': 'Développement',
      'shell': 'Shell',
      'file': 'Fichier',
      'http': 'HTTP',
      'api': 'API',
      'artifact': 'Artéfact',
      'audio': 'Audio'
    };

    const k = kindMap[kind] || kind || 'Inconnu';
    const t = toolMap[tool] || tool || 'Inconnu';

    // État d’activité
    if (result && (result.state === 'running' || result.state === 'queued' || result.state === 'publishing')) {
      this.onState('thinking');
    } else {
      this.onState('listening');
    }

    // Action humaine/automatisée
    const human = actor ? (actor.startsWith('user_') || actor.includes('humain') ? ' humain' : '');
    if (kind === 'act') {
      return `${t} (${k}${human})`;
    } else {
      return `${k} (${t}${human})`;
    }
  }

  get diagnostics() {
    const cached = this.id ? this.cache.get(this.id) : null;
    return {
      mission: this.id,
      cursor: cached ? cached.cursor : 0,
      eventCount: cached ? cached.events.length : 0,
      polling: this.running
    };
  }
}

import { api } from './api.js';

export class VoiceController {
  constructor(callbacks) {
    this.callbacks = callbacks;
    this.ctx = null;
    this.analyser = null;
    this.gainNode = null;
    this.mediaStream = null;
    this.recorder = null;
    this.chunks = [];
    this.rAFId = null;
    this.lastSpeech = 0;
    this.hasSpeech = false;
    this.micEnabled = false;
    this.speechEpoch = 0;
    this.audio = null;
    this.sttQueue = Promise.resolve();
  }

  async startMic() {
    try {
      this.mediaStream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        }
      });
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      this.analyser = this.ctx.createAnalyser();
      this.analyser.fftSize = 512;
      this.gainNode = this.ctx.createGain();
      this.gainNode.gain.value = 1.0;
      const source = this.ctx.createMediaStreamSource(this.mediaStream);
      source.connect(this.gainNode);
      this.gainNode.connect(this.ctx.destination);
      this.micEnabled = true;
      this.chunks = [];
      this.startSegment();
      this.processRMS();
    } catch (err) {
      console.error('startMic error:', err);
      this.micEnabled = false;
      this.callbacks.onError?.('Mic access refused');
    }
  }

  async startSegment() {
    const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
      ? 'audio/webm;codecs=opus'
      : MediaRecorder.isTypeSupported('audio/mp4')
        ? 'audio/mp4'
        : '';
    if (!mimeType) {
      this.callbacks.onError?.('No supported audio codec found');
      return;
    }
    this.recorder = new MediaRecorder(this.mediaStream, { mimeType });
    this.recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        this.chunks.push(e.data);
      }
    };
    this.recorder.onstop = async () => {
      const hadSpeech = this.hasSpeech;
      this.hasSpeech = false;
      const blob = new Blob(this.chunks, { type: this.recorder.mimeType });
      if (hadSpeech) {
        this.sttQueue = this.sttQueue.then(async () => {
          try {
            const text = await api('/api/stt', blob);
            this.callbacks.onTranscript?.(text);
          } catch (err) {
            this.callbacks.onError?.('STT failed: ' + err.message);
          }
        });
      }
      if (this.micEnabled) {
        this.chunks = [];
        this.startSegment();
      }
    };
    this.recorder.start(1000);
  }

  processRMS() {
    if (!this.ctx) return;
    const bufferLength = this.analyser.fftSize;
    const dataArray = new Float32Array(bufferLength);
    const checkRMS = () => {
      if (!this.micEnabled) return;
      this.analyser.getFloatTimeDomainData(dataArray);
      let sum = 0;
      for (let i = 0; i < bufferLength; i++) {
        sum += dataArray[i] * dataArray[i];
      }
      const rms = Math.sqrt(sum / bufferLength);
      const now = Date.now();
      if (rms > 0.02) {
        this.lastSpeech = now;
        if (!this.hasSpeech) {
          this.hasSpeech = true;
        }
        if (this.audio && this.audio.paused === false && now - this.lastSpeech > 200) {
          this.interruptAudio();
        }
      }
      if (this.hasSpeech && now - this.lastSpeech > 700) {
        this.recorder.stop();
      }
      this.rAFId = requestAnimationFrame(checkRMS);
    };
    this.rAFId = requestAnimationFrame(checkRMS);
  }

  stopMic() {
    this.micEnabled = false;
    if (this.recorder && this.recorder.state !== 'inactive') {
      this.recorder.stop();
    }
    if (this.rAFId) {
      cancelAnimationFrame(this.rAFId);
      this.rAFId = null;
    }
    if (this.mediaStream) {
      this.mediaStream.getTracks().forEach(track => track.stop());
      this.mediaStream = null;
    }
    if (this.ctx && this.ctx.close) {
      this.ctx.close();
      this.ctx = null;
    }
  }

  async speak(text) {
    const epoch = ++this.speechEpoch;
    this.callbacks.onState?.('thinking');
    try {
      const blob = await api('/api/tts', { text });
      if (this.speechEpoch !== epoch) return;
      const objectURL = URL.createObjectURL(blob);
      this.audio = new Audio(objectURL);
      this.audio.onended = () => {
        URL.revokeObjectURL(objectURL);
        this.callbacks.onState?.('listening');
      };
      this.audio.onpause = () => {
        URL.revokeObjectURL(objectURL);
      };
      this.callbacks.onAudio?.(this.audio);
      try {
        await this.audio.play();
        this.callbacks.onState?.('speaking');
      } catch (err) {
        this.callbacks.onError?.('Playback refused: ' + err.message);
        URL.revokeObjectURL(objectURL);
      }
    } catch (err) {
      this.callbacks.onError?.('TTS failed: ' + err.message);
    }
  }

  interruptAudio() {
    this.speechEpoch++;
    if (this.audio && this.audio.paused === false) {
      this.audio.pause();
    }
  }
}

import { api } from './api.js';

export class VoiceController {
  constructor(callbacks) {
    this.callbacks = callbacks;
    this.onState = callbacks.onState || (() => {});
    this.onTranscript = callbacks.onTranscript || (() => {});
    this.onError = callbacks.onError || (() => {});
    this.onAudio = callbacks.onAudio || (() => {});

    this.ctx = null;
    this.analyser = null;
    this.microphone = null;
    this.gainNode = null;
    this.rafId = null;
    this.recorder = null;
    this.chunks = [];
    this.micEnabled = false;
    this.hasSpeech = false;
    this.lastSpeech = 0;
    this.speechEpoch = 0;
    this.audio = null;

    this.sttQueue = Promise.resolve();
  }

  async startMic() {
    if (this.micEnabled) return;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        }
      });

      this.ctx = new AudioContext();
      this.microphone = this.ctx.createMediaStreamSource(stream);
      this.gainNode = this.ctx.createGain();
      this.gainNode.gain.value = 0;
      this.microphone.connect(this.gainNode);
      this.gainNode.connect(this.ctx.destination);

      this.analyser = this.ctx.createAnalyser();
      this.analyser.fftSize = 512;
      this.microphone.connect(this.analyser);

      this.micEnabled = true;

      this.startSegment();

      this.rmsLoop();
    } catch (err) {
      this.onError(`microphone access: ${err.message}`);
    }
  }

  rmsLoop() {
    const buffer = new Float32Array(this.analyser.fftSize);
    let silenceStart = 0;
    const threshold = 0.02;

    const loop = () => {
      if (!this.micEnabled) return;

      this.analyser.getFloatRMSData(buffer);
      const rms = buffer[0];

      if (rms > threshold) {
        this.lastSpeech = Date.now();
        this.hasSpeech = true;
        silenceStart = 0;

        if (this.audio && !this.audio.paused) {
          const speakingDuration = Date.now() - this.lastSpeech;
          if (speakingDuration > 200) {
            this.interruptAudio();
          }
        }
      } else {
        if (this.hasSpeech) {
          const silenceDuration = Date.now() - this.lastSpeech;
          if (silenceDuration >= 700 || (Date.now() - this.lastSpeech >= 20000)) {
            if (this.recorder && this.recorder.state === 'recording') {
              this.recorder.stop();
            }
          }
        }
      }

      this.rafId = requestAnimationFrame(loop);
    };

    this.rafId = requestAnimationFrame(loop);
  }

  async startSegment() {
    const supportedTypes = ['audio/webm;codecs=opus', 'audio/mp4'];
    let mimeType = supportedTypes.find((type) => MediaRecorder.isTypeSupported(type)) || '';

    try {
      this.chunks = [];
      this.recorder = new MediaRecorder(this.microphone.stream, mimeType ? { mimeType } : undefined);

      this.recorder.ondataavailable = (e) => {
        if (e.data.size > 0) this.chunks.push(e.data);
      };

      this.recorder.onstop = async () => {
        const hadSpeech = this.hasSpeech;
        this.hasSpeech = false;
        const blob = new Blob(this.chunks, { type: this.recorder.mimeType });

        if (hadSpeech) {
          await this.sttQueue;
          this.sttQueue = (async () => {
            try {
              this.onState('transcribing');
              const text = await api('/api/stt', blob);
              this.onTranscript(text);
            } catch (err) {
              this.onError(`STT error: ${err.message}`);
            }
            if (this.micEnabled) {
              this.startSegment();
            }
          })();
        } else if (this.micEnabled) {
          this.startSegment();
        }
      };

      this.recorder.start();
    } catch (err) {
      this.onError(`segment start: ${err.message}`);
      if (this.micEnabled) {
        this.startSegment();
      }
    }
  }

  async stopMic() {
    this.micEnabled = false;

    if (this.recorder) this.recorder.stop();
    if (this.rafId) cancelAnimationFrame(this.rafId);

    if (this.microphone && this.microphone.stream) {
      const tracks = this.microphone.stream.getTracks();
      tracks.forEach((track) => track.stop());
    }

    if (this.ctx && this.ctx.state !== 'closed') {
      this.ctx.close().catch(() => {});
    }

    this.microphone = null;
    this.ctx = null;
    this.analyser = null;
    this.gainNode = null;
  }

  async speak(text) {
    const epoch = ++this.speechEpoch;

    this.onState('thinking');
    try {
      const blob = await api('/api/tts', { text });

      if (this.speechEpoch !== epoch) return;

      const objectURL = URL.createObjectURL(blob);
      this.audio = new Audio(objectURL);
      this.onAudio(this.audio);

      this.audio.onended = () => {
        URL.revokeObjectURL(objectURL);
        this.onState('listening');
      };

      this.audio.onpause = () => {
        URL.revokeObjectURL(objectURL);
        this.onState('listening');
      };

