    this.analyser = null;
    this.gainNode = null;
    this.recorder = null;
    this.stream = null;
    this.animationFrame = null;
    this.localChunks = [];
    this.sttQueue = [];
    this.sttRunning = false;
  }

  async startMic() {
    if (this.micEnabled) return;
    try {
      this.stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        }
      });

