    if (!text) return;
    const epoch = ++this.speechEpoch;
    this.onState('thinking');

    try {
      const response = await api('/api/tts', { text });
      const blob = await response.blob();
      if (epoch !== this.speechEpoch) return;

      const objectURL = URL.createObjectURL(blob);
      this.audio = new Audio(objectURL);
      this.audio.onended = () => {
        URL.revokeObjectURL(objectURL);
        this.audio = null;
        this.onState('listening');
      };
      this.audio.onpause = () => {
        URL.revokeObjectURL(objectURL);
        this.audio = null;
        this.onState('listening');
      };
      this.onAudio(this.audio);

      try {
        await this.audio.play();
        this.onState('speaking');
      } catch (err) {
        URL.revokeObjectURL(objectURL);
        this.audio = null;
        this.onError(`Playback failed: ${err.message}`);
      }
    } catch (err) {
      this.onError(`TTS error: ${err.message}`);
    }
  }

  interruptAudio() {
    this.speechEpoch++;
    if (this.audio) {
      this.audio.pause();
      this.audio = null;
    }
  }

  startSegment() {
    const supportedTypes = ['audio/webm;codecs=opus', 'audio/mp4;codecs=opus'];
    let mimeType = 'audio/webm;codecs=opus';
    for (const type of supportedTypes) {
      if (MediaRecorder.isTypeSupported(type)) {
        mimeType = type;
        break;
      }
    }

    const stream = this.stream;
    if (!stream) return;

    this.recorder = new MediaRecorder(stream, { mimeType });
    this.recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        this.localChunks.push(e.data);
      }
    };

    this.recorder.onstop = async () => {
      const hadSpeech = this.hasSpeech;
      this.hasSpeech = false;
      this.localChunks = [];

      if (!this.micEnabled) return;

      if (hadSpeech) {
        const blob = new Blob(this.localChunks, { type: this.recorder.mimeType });
        await this.submitSTT(blob);
      }

      // Restart segment only if still enabled and not interrupted by TTS
      if (this.micEnabled) {
        this.startSegment();
      }
    };

    try {
      this.recorder.start(100);
    } catch (err) {
      this.onError(`Recorder start error: ${err.message}`);
    }
  }

  async submitSTT(blob) {
    if (!blob || blob.size === 0) return;

    this.sttQueue.push(blob);
    if (this.sttRunning) return;

    this.sttRunning = true;
    while (this.sttQueue.length > 0) {
      const item = this.sttQueue.shift();
      try {
        const response = await api('/api/stt', item);
        const result = await response.json();
        if (result.text) {
          this.onTranscript(result.text);
        }
      } catch (err) {
        this.onError(`STT error: ${err.message}`);
      }
    }
    this.sttRunning = false;
  }

  rmsLoop() {
    const now = Date.now();
    const buffer = new Float32Array(512);

    if (this.micEnabled) {
      this.analyser.getFloatTimeDomainData(buffer);
      let sum = 0;
      for (let i = 0; i < buffer.length; i++) {
        sum += buffer[i] * buffer[i];
      }
      const rms = Math.sqrt(sum / buffer.length);

      if (rms > this.rmsThreshold) {
        if (!this.hasSpeech) {
          this.speechDetectedTime = now;
          this.hasSpeech = true;
        }
        this.lastSpeech = now;
        if (this.hasSpeech && this.audio && (now - this.speechDetectedTime) >= this.interruptionDelay) {
          this.interruptAudio();
        }
      } else if (this.hasSpeech && (now - this.lastSpeech) >= this.silenceDuration) {
        if (this.recorder && this.recorder.state === 'recording') {
          this.recorder.stop();
        }
        this.hasSpeech = false;
      } else if (this.hasSpeech && (now - this.speechDetectedTime) >= this.maxSegmentDuration) {
        if (this.recorder && this.recorder.state === 'recording') {
          this.recorder.stop();
        }
        this.hasSpeech = false;
      }

      this.animationFrame = requestAnimationFrame(() => this.rmsLoop());
    }
  }
}

