    this.analyser = null;
    this.gainNode = null;
    this.stream = null;
    this.recorder = null;
    this.frameId = null;
    this.sttQueue = Promise.resolve();
  }

  async startMic() {
    if (this.micEnabled) return;

    this.stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
      },
    });

    this.ctx = new AudioContext();
    const src = this.ctx.createMediaStreamSource(this.stream);
    this.gainNode = this.ctx.createGain();
    this.gainNode.gain.value = 0; // pas de feedback
    src.connect(this.gainNode);
    this.gainNode.connect(this.ctx.destination);

    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 512;
    this.stream.getAudioTracks()[0].addEventListener('ended', () => {
      this.micEnabled = false;
    });

    this.micEnabled = true;
    this.lastSpeech = performance.now();
    this.segmentStart = this.lastSpeech;
    this.sttQueue = Promise.resolve();
    this.startSegment();
    this.analyseLoop();
  }

  async analyseLoop() {
    const data = new Float32Array(512);
    const threshold = 0.02;

    const loop = () => {
      if (!this.micEnabled || !this.analyser) {
        this.frameId = null;
        return;
      }

      this.analyser.getFloatTimeDomainData(data);
      let sum = 0;
      for (let i = 0; i < data.length; i++) {
        const v = Math.abs(data[i]);
        sum += v * v;
      }
      const rms = Math.sqrt(sum / data.length);
      const now = performance.now();

      if (rms >= threshold) {
        this.lastSpeech = now;
        this.hasSpeech = true;
        // Interruption TTS si parole > 200 ms (et TTS actif)
        if (this.audio && !this.audio.paused && (now - this.lastSpeech) > 200) {
          this.interruptAudio();
        }
      } else if (this.hasSpeech && (now - this.lastSpeech > 700)) {
        // Silence prolongé : stopper le segment
        if (this.recorder) {
          this.recorder.stop();
        }
      } else if (this.hasSpeech && (now - this.segmentStart > 20000)) {
        // Segment max 20 s
        if (this.recorder) {
          this.recorder.stop();
        }
      }

      this.frameId = requestAnimationFrame(loop);
    };

    this.frameId = requestAnimationFrame(loop);
  }

  startSegment() {
    const mimeTypes = ['audio/webm;codecs=opus', 'audio/mp4;codecs=mp4a.40.2'];
    let mimeType = 'audio/webm';

    for (const t of mimeTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
        mimeType = t;
        break;
      }
    }

    this.chunks = [];
    this.recorder = new MediaRecorder(this.stream, { mimeType });
    this.recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        this.chunks.push(e.data);
      }
    };
    this.recorder.onstop = () => {
      const hadSpeech = this.hasSpeech;
      const blob = new Blob(this.chunks, { type: this.recorder.mimeType });

      // Redémarrer un nouveau segment si micEnabled
      this.hasSpeech = false;
      this.segmentStart = performance.now();
      if (this.micEnabled) {
        this.startSegment();
      }

      if (!hadSpeech) return;

      // Soumission séquentielle via file Promise
      this.sttQueue = this.sttQueue
        .then(() => api('/api/stt', blob))
        .then((text) => {
          if (typeof text === 'string' && text.length > 0) {
            this.onTranscript(text);
          }
        })
        .catch((err) => {
          this.onError(`STT error: ${err?.message || String(err)}`);
        });
    };

    this.recorder.start(500); // dataavailable toutes les 500 ms
  }

  async stopMic() {
    this.micEnabled = false;
    if (this.recorder && this.recorder.state !== 'inactive') {
      this.recorder.stop();
    }
    if (this.frameId) {
      cancelAnimationFrame(this.frameId);
      this.frameId = null;
    }
    if (this.stream) {
      this.stream.getTracks().forEach((t) => t.stop());
      this.stream = null;
    }
    if (this.ctx && this.ctx.state !== 'closed') {
      // .close() peut ne pas être async selon implémentation
      try {
        await this.ctx.close();
      } catch {
        this.ctx.close(); // fallback sans await si non supporté
      }
      this.ctx = null;
    }
  }

  async speak(text) {
    const epoch = ++this.speechEpoch;
    this.onState('thinking');

    let blob;
    try {
      blob = await api('/api/tts', { text });
    } catch (err) {
      this.onError(`TTS request failed: ${err?.message || String(err)}`);
      return;
    }

    // Ignorer si interrompu pendant requête
    if (epoch !== this.speechEpoch) return;

    this.onState('speaking');

    let audio;
    try {
      const url = URL.createObjectURL(blob);
      audio = new Audio(url);
      audio.addEventListener('ended', () => {
        URL.revokeObjectURL(url);
        if (this.speechEpoch === epoch) {
          this.onState('listening');
        }
      });
      audio.addEventListener('error', () => {
        URL.revokeObjectURL(url);
        this.onError('Audio playback error');
        if (this.speechEpoch === epoch) {
          this.onState('listening');
        }
      });
      this.onAudio(audio);
      this.audio = audio;
      await audio.play();
    } catch (err) {
      this.onError(`Audio play failed: ${err?.message || String(err)}`);
    }
  }

  interruptAudio() {
    this.speechEpoch++;
    if (this.audio) {
      this.audio.pause();
    }
  }
}

