    this.analyser = null;
    this.gainNode = null;
    this.microphoneStream = null;
    this.rafId = null;
    this.recorder = null;
    this.chunks = [];
    this.hasSpeech = false;
    this.lastSpeech = 0;
    this.micEnabled = false;
    this.audio = null;
    this.speechEpoch = 0;
    this.speakingEpoch = 0;
    this.sttQueue = Promise.resolve();
  }

