    const source = this.ctx.createMediaStreamSource(this.microphoneStream);
    this.gainNode = this.ctx.createGain();
    this.gainNode.gain.value = 0.0;
    source.connect(this.gainNode);
    this.gainNode.connect(this.ctx.destination);

    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 512;
    source.connect(this.analyser);

    this.micEnabled = true;
    this.startSegment();
    this.rmsLoop();
  }

  async rmsLoop() {
    const buffer = new Float32Array(512);
    let lastRmsTime = performance.now();

    const loop = () => {
      if (!this.micEnabled || !this.analyser) {
        this.rafId = null;
        return;
      }

      this.analyser.getFloatTimeDomainData(buffer);
      let sum = 0;
      for (let i = 0; i < buffer.length; i++) {
        const v = buffer[i];
        sum += v * v;
      }
      const rms = Math.sqrt(sum / buffer.length);

      const now = performance.now();
      if (rms > 0.02) {
        this.hasSpeech = true;
        this.lastSpeech = now;
      }

      const silenceFor = now - this.lastSpeech;

      // Si silence depuis >= 700 ms après parole, ou silence depuis 20 secondes
      if ((this.hasSpeech && silenceFor >= 700) || (!this.hasSpeech && silenceFor >= 20000)) {
        if (this.recorder && this.recorder.state === 'recording') {
          this.recorder.stop();
        }
      }

      // interruption TTS si parole détectée + 200 ms
      if (this.hasSpeech && this.speakingEpoch !== this.speechEpoch && now - this.lastSpeech >= 200) {
        this.interruptAudio();
      }

      this.rafId = requestAnimationFrame(loop);
    };

    this.rafId = requestAnimationFrame(loop);
  }

  startSegment() {
    if (!this.micEnabled) return;

    const mimeType =
      MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
        ? 'audio/webm;codecs=opus'
        : MediaRecorder.isTypeSupported('audio/mp4')
          ? 'audio/mp4'
          : null;

    if (!mimeType) {
      this.onError(new Error('No supported audio recorder MIME type found'));
      return;
    }

    this.chunks = [];
    try {
      this.recorder = new MediaRecorder(this.microphoneStream, { mimeType });
    } catch (err) {
      this.onError(new Error(`MediaRecorder initialization failed: ${err.message}`));
      return;
    }

    this.recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        this.chunks.push(e.data);
      }
    };

    this.recorder.onstop = () => {
      if (!this.micEnabled) return;

      const hadSpeech = this.hasSpeech;
      const currentBlob = new Blob(this.chunks, { type: this.recorder.mimeType });

      if (hadSpeech) {
        this.sttQueue = this.sttQueue.then(async () => {
          try {
            const text = await api('/api/stt', currentBlob);
            this.onTranscript(text);
          } catch (err) {
            this.onError(new Error(`STT failed: ${err.message}`));
          }
        });
      }

      this.hasSpeech = false;
      this.startSegment();
    };

    this.recorder.start(1000);
  }

  async stopMic() {
    this.micEnabled = false;

    if (this.recorder && this.recorder.state !== 'inactive') {
      try {
        this.recorder.stop();
      } catch (_) {
        // ignore
      }
    }

    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }

    if (this.microphoneStream) {
      const tracks = this.microphoneStream.getTracks();
      tracks.forEach((t) => t.stop());
      this.microphoneStream = null;
    }

    if (this.ctx && this.ctx.state !== 'closed') {
      // Firefox nécessite un await ; Chrome peut accepter sans.
      // On déclare async ici, donc on appelle avec await.
      try {
        await this.ctx.close();
      } catch (_) {
        // ignore
      }
      this.ctx = null;
    }
  }

  async speak(text) {
    if (!text) {
      this.onError(new Error('Text empty'));
      return;
    }

    const epoch = ++this.speechEpoch;
    this.onState('thinking');

    let blob;
    try {
      blob = await api('/api/tts', { text });
    } catch (err) {
      this.onError(new Error(`TTS request failed: ${err.message}`));
      this.onState('listening');
      return;
    }

    if (this.speechEpoch !== epoch) return;

    let url;
    try {
      url = URL.createObjectURL(blob);
    } catch (err) {
      this.onError(new Error(`ObjectURL creation failed: ${err.message}`));
      this.onState('listening');
      return;
    }

    this.audio = new Audio(url);
    this.onAudio(this.audio);

    let resolved = false;
    const cleanup = () => {
      if (!resolved) {
        resolved = true;
        URL.revokeObjectURL(url);
        if (this.speechEpoch === epoch) {
          this.onState('listening');
        }
      }
    };

    this.audio.onended = cleanup;
    this.audio.onerror = (e) => {
      this.onError(new Error(`Audio playback error: ${e.message || 'unknown'}`));
      cleanup();
    };

    this.onState('speaking');

    try {
      await this.audio.play();
    } catch (err) {
      this.onError(new Error(`Play failed: ${err.message}`));
      cleanup();
      return;
    }

    // attendre ended/pause/erreur via events (déjà géré)
    // On ne retourne rien de specifique ici; l'attente réelle se fait à l'extérieur si besoin.
  }

  interruptAudio() {
    this.speechEpoch++;
    if (this.audio) {
      try {
        this.audio.pause();
      } catch (_) {
        // ignore
      }
    }
    this.hasSpeech = false;
    this.lastSpeech = 0;
    this.onState('listening');
  }
}

