        URL.revokeObjectURL(url);
        this.callbacks.onError(`Audio playback failed: ${e.type}`);
        this.callbacks.onState('listening');
      };

      this.currentTTS = this.audio;
      this.callbacks.onAudio(this.audio);

      try {
        await this.audio.play();
        this.callbacks.onState('speaking');
      } catch (playError) {
        this.callbacks.onError(`Impossible de jouer l’audio: ${playError.message}`);
        this.audio = null;
        this.currentTTS = null;
