export class VoiceController {
  constructor(callbacks = {}) {
    this.callbacks = callbacks;
    this.onTranscript = callbacks.onTranscript || (() => {});
    this.onError = callbacks.onError || ((e) => console.error('Voice error:', e));
    this.onState = callbacks.onState || (() => {});
    this.onAudio = callbacks.onAudio || (() => {});

    this.audioCtx = null;
    this.analyser = null;
    this.microphone = null;
    this.gainNode = null;
    this.rafId = null;
    this.recorder = null;
    this.chunks = [];
    this.hasSpeech = false;
    this.lastSpeech = 0;
    this.micEnabled = false;
    this.speechEpoch = 0;
    this.audio = null;
    this.speechSegments = 0;
    this.maxSpeechSegments = 5;
    this.speechSegmentsTimer = null;

    this.sttQueue = Promise.resolve();
  }

  async startMic() {
    if (this.micEnabled) return;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        }
      });

      this.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      this.analyser = this.audioCtx.createAnalyser();
      this.analyser.fftSize = 512;

      this.microphone = this.audioCtx.createMediaStreamSource(stream);
      this.gainNode = this.audioCtx.createGain();
      this.gainNode.gain.value = 1.0;

      // Connexion : micro → gain → destination (sans rétroaction sur l'analyse)
      this.microphone.connect(this.gainNode);
      this.gainNode.connect(this.audioCtx.destination);

      // Connexion pour l'analyse (pas dans le chemin de destination)
      this.microphone.connect(this.analyser);

      this.micEnabled = true;
      this.startSegment();

      this.rmsLoop();
    } catch (e) {
      this.onError(e);
      throw e;
    }
  }

  async rmsLoop() {
    const buffer = new Float32Array(512);
    const threshold = 0.02;
    const silenceThreshold = 700;
    const speechTimeout = 200;
    const segmentDuration = 20000;

    const loop = () => {
      if (!this.micEnabled) return;

      this.analyser.getFloatTimeDomainData(buffer);
      let sum = 0;
      for (let i = 0; i < buffer.length; i++) {
        sum += buffer[i] * buffer[i];
      }
      const rms = Math.sqrt(sum / buffer.length);

      const now = Date.now();

      if (rms > threshold) {
        this.lastSpeech = now;
        if (!this.hasSpeech) {
          this.hasSpeech = true;
          this.speechSegments = 1;
        }
      } else {
        if (this.hasSpeech && (now - this.lastSpeech > silenceThreshold)) {
          // Silence prolongé après parole → terminer le segment
          if (this.recorder && this.recorder.state === 'recording') {
            this.recorder.stop();
          }
        }
      }

      // Durée maximale par segment
      if (this.hasSpeech && (now - this.lastSpeech > segmentDuration)) {
        if (this.recorder && this.recorder.state === 'recording') {
          this.recorder.stop();
        }
      }

      // Si TTS en cours et parole détectée pendant plus de 200 ms
      if (this.speechEpoch > 0 && this.hasSpeech && (now - this.lastSpeech > speechTimeout)) {
        this.interruptAudio();
      }

      this.rafId = requestAnimationFrame(loop);
    };

    this.rafId = requestAnimationFrame(loop);
  }

  async stopMic() {
    this.micEnabled = false;

    // Arrêter la boucle
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }

    // Arrêter le recorder
    if (this.recorder) {
      try {
        this.recorder.stop();
      } catch (_) {
        // ignore si déjà stoppé
      }
    }

    // Arrêter les pistes du stream
    if (this.microphone) {
      const tracks = this.microphone.stream.getTracks();
      tracks.forEach(track => track.stop());
      this.microphone.disconnect();
      this.microphone = null;
    }

    // Fermer le contexte audio (sans await car méthode synchrone ou non garantie)
    if (this.audioCtx) {
      try {
        await this.audioCtx.close();
      } catch (_) {
        this.audioCtx.close();
      }
      this.audioCtx = null;
    }

    // Nettoyer
    this.chunks = [];
    this.hasSpeech = false;
  }

  async startSegment() {
    const supportedTypes = ['audio/webm;codecs=opus', 'audio/mp4;codecs=opus'];
    let mimeType = 'audio/webm;codecs=opus';

    for (const type of supportedTypes) {
      if (MediaRecorder.isTypeSupported(type)) {
        mimeType = type;
        break;
      }
    }

    this.chunks = [];
    this.recorder = new MediaRecorder(this.microphone.stream, { mimeType });

    this.recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        this.chunks.push(e.data);
      }
    };

    this.recorder.onstop = async () => {
      const hadSpeech = this.hasSpeech;

      // Construire le blob
      const blob = new Blob(this.chunks, { type: this.recorder.mimeType });

      // Reset
      this.hasSpeech = false;
      this.lastSpeech = 0;

      // Si pas de parole, on ne transcrit pas
      if (!hadSpeech) {
        this.startSegment();
        return;
      }

      // Ajouter à la file
      this.sttQueue = this.sttQueue.then(async () => {
        try {
          const transcript = await api('/api/stt', blob);
          this.onTranscript(transcript);
          this.speechSegments++;
        } catch (e) {
          this.onError(e);
        }

        // Si encore activé et pas dépassé max segments
        if (this.micEnabled && this.speechSegments < this.maxSpeechSegments) {
          this.startSegment();
        } else if (this.micEnabled) {
          // Reset segment count
          this.speechSegments = 0;
          this.startSegment();
        }
      });
    };

    if (this.recorder.state === 'inactive') {
      this.recorder.start();
    }
  }

  async speak(text) {
    this.onState('thinking');

    const epoch = ++this.speechEpoch;

    try {
      const blob = await api('/api/tts', { text });

      // Vérifier qu'un nouveau speak n'a pas été initié
      if (this.speechEpoch !== epoch) {
        this.onState('listening');
        return;
      }

      // Créer l'audio
      const objectUrl = URL.createObjectURL(blob);
      this.audio = new Audio(objectUrl);
      this.onAudio(this.audio);

      let completed = false;

      const finish = () => {
        if (completed) return;
        completed = true;
        URL.revokeObjectURL(objectUrl);
        this.onState('listening');
      };

      this.audio.onended = finish;
      this.audio.onpause = finish;
      this.audio.onerror = (e) => {
        this.onError('Audio playback error: ' + e);
        finish();
      };

      try {
        await this.audio.play();
        this.onState('speaking');
      } catch (e) {
        this.onError('Playback failed: ' + e);
        finish();
        return;
      }

      // Attendre la fin ou pause
      await new Promise((resolve, reject) => {
        const cleanup = () => {
          this.audio.onended = null;
          this.audio.onpause = null;
          this.audio.onerror = null;
        };

        this.audio.onended = () => {
          cleanup();
          resolve();
        };

        this.audio.onpause = () => {
          cleanup();
          resolve();
        };

        this.audio.onerror = (e) => {
          cleanup();
          reject(e);
        };
      });
    } catch (e) {
      this.onError(e);
      this.onState('listening');
    }
  }

  interruptAudio() {
    this.speechEpoch++;
    if (this.audio) {
      try {
        this.audio.pause();
      } catch (_) {
        // ignore
      }
    }
  }
}

