      this.analyser = this.ctx.createAnalyser();
      this.analyser.fftSize = 512;

      source.connect(this.gainNode);
      this.gainNode.connect(this.ctx.destination);

      this.lastSpeech = performance.now();
      this.micEnabled = true;
      this.startSegment();
      this.monitorSpeech();
      this.onState('listening');
    } catch (err) {
      this.onError('startMic: ' + err.message);
      throw err;
    }
  }

  async monitorSpeech() {
    const data = new Float32Array(this.analyser.fftSize);
    const threshold = 0.02;
    const silenceDuration = 700;
    const minSpeechDuration = 200;
    let speechTimer = 0;

    const loop = () => {
      if (!this.micEnabled || !this.ctx) return;
      this.analyser.getFloatTimeDomainData(data);
      let sum = 0;
      for (let i = 0; i < data.length; i++) {
        sum += data[i] * data[i];
      }
      const rms = Math.sqrt(sum / data.length);

      if (rms >= threshold) {
        this.lastSpeech = performance.now();
        this.hasSpeech = true;
        speechTimer += 100;
        if (this.audio && speechTimer >= minSpeechDuration) {
          this.interruptAudio();
        }
      } else {
        if (this.hasSpeech && performance.now() - this.lastSpeech > silenceDuration) {
          this.recorder.stop();
        }
      }

      this.rafId = requestAnimationFrame(loop);
    };

    this.rafId = requestAnimationFrame(loop);
  }

  startSegment() {
    const types = ['video/webm;codecs=opus', 'video/mp4;codecs=mp4a'];
    let mimeType = 'video/webm;codecs=opus';
    for (const t of types) {
      if (MediaRecorder.isTypeSupported(t)) {
        mimeType = t;
        break;
      }
    }

    this.chunks = [];
    this.recorder = new MediaRecorder(this.stream, { mimeType });
    this.recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        this.chunks.push(e.data);
      }
    };

    this.recorder.onstop = () => {
      const hadSpeech = this.hasSpeech;
      const blob = new Blob(this.chunks, { type: this.recorder.mimeType });

      // Redémarrer segment si mic activé
      if (this.micEnabled) {
        this.hasSpeech = false;
        this.startSegment();
      }

      // Soumission STT si parole détectée
      if (hadSpeech) {
        this.sttQueue = this.sttQueue.then(() =>
          api('/api/stt', blob)
            .then((text) => {
              if (text && text.trim()) {
                this.onTranscript(text);
              }
            })
            .catch((err) => {
              this.onError('STT: ' + err.message);
            })
        );
      }
    };

    this.recorder.start(100); // 100 ms segments
  }

  async stopMic() {
    this.micEnabled = false;
    if (this.recorder && this.recorder.state !== 'inactive') {
      this.recorder.stop();
    }
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    if (this.stream) {
      const tracks = this.stream.getTracks();
      tracks.forEach(t => t.stop());
      this.stream = null;
    }
    if (this.ctx && this.ctx.state !== 'closed') {
      try {
        this.ctx.close();
      } catch {
        // ignore if already closed or non-async
      }
      this.ctx = null;
    }
  }

  async speak(text) {
    const epoch = ++this.speechEpoch;
    this.onState('thinking');

    try {
      const blob = await api('/api/tts', { text });
      if (epoch !== this.speechEpoch) return;

      const objectURL = URL.createObjectURL(blob);
      this.audio = new Audio(objectURL);
      this.onAudio(this.audio);

      let resolved = false;
      const cleanup = () => {
        if (!resolved) {
          resolved = true;
          URL.revokeObjectURL(objectURL);
        }
        if (this.audio) {
          this.audio.onended = null;
          this.audio.onpause = null;
        }
      };

      this.audio.onended = () => {
        cleanup();
        this.onState('listening');
      };

      this.audio.onpause = () => {
        cleanup();
        this.onState('listening');
      };

      try {
        await this.audio.play();
        this.onState('speaking');
      } catch (err) {
        this.onError('play: ' + err.message);
        cleanup();
        this.onState('listening');
        throw err;
      }

    } catch (err) {
      this.onError('speak: ' + err.message);
      throw err;
    }
  }

  interruptAudio() {
    this.speechEpoch++;
    if (this.audio) {
      this.audio.pause();
    }
  }
}

import { api } from './api.js';

/**
 * VoiceController : gestion de la reconnaissance vocale (STT) et synthèse (TTS)
 * pas de champ privé, pas de LiveKit, pas d'accès direct au chat/mission
 * API : api('/api/stt', blob) → {text}
 *       api('/api/tts', {text}) → Blob (audio)
 */
export class VoiceController {
  constructor(callbacks) {
    this.callbacks = callbacks || {};
    this.micEnabled = false;
    this.ctx = null;
    this.analyser = null;
    this.gainNode = null;
    this.recorder = null;
    this.chunks = [];
    this.animId = null;
    this.lastSpeech = 0;
    this.hasSpeech = false;
    this.speechEpoch = 0;
    this.audio = null;
    this.sttQueue = Promise.resolve();
  }

  // Détecte le codec supporté pour le microphone
  #getPreferredMimeType() {
    const candidates = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4;codecs=opus', 'audio/ogg;codecs=opus'];
    for (const m of candidates) {
      if (MediaRecorder.isTypeSupported(m)) return m;
    }
    return '';
  }

  // Démarrage d'un nouveau segment d'enregistrement
  startSegment() {
    const mimeType = this.#getPreferredMimeType();
    this.chunks = [];
    this.recorder = new MediaRecorder(this.ctx ? this.ctx.createMediaStreamSource(this.stream) : new MediaStream(), mimeType ? { mimeType } : {});
    this.recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) this.chunks.push(e.data);
    };
    this.recorder.onstop = () => {
      const hadSpeech = this.hasSpeech;
      this.hasSpeech = false;

      if (hadSpeech && this.chunks.length > 0) {
        const blob = new Blob(this.chunks, { type: this.recorder.mimeType });
        // Enfile la transcription, évite chevauchement
        this.sttQueue = this.sttQueue.then(() => api('/api/stt', blob).then((data) => {
          if (data && data.text && typeof this.callbacks.onTranscript === 'function') {
            this.callbacks.onTranscript(data.text);
          }
        }).catch(() => {}));
      }

      if (this.micEnabled) {
        this.startSegment();
        this.recorder.start(20000); // 20s max par segment
      }
    };
    this.recorder.start(20000);
  }

  // Démarrage du micro avec permission, analyse active
  async startMic() {
    if (this.micEnabled) return;

    this.stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true
      }
    });

    this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 512;
    this.gainNode = this.ctx.createGain();
    this.gainNode.gain.value = 0;

    const source = this.ctx.createMediaStreamSource(this.stream);
    source.connect(this.gainNode);
    this.gainNode.connect(this.ctx.destination);

    this.micEnabled = true;
    this.lastSpeech = 0;
    this.hasSpeech = false;
    this.startSegment();
    this.recorder.start(20000);

    const buffer = new Float32Array(512);
    const analyze = () => {
      if (!this.micEnabled || !this.analyser) return;
      this.analyser.getFloatTimeDomainData(buffer);
      let sum = 0;
      for (let i = 0; i < buffer.length; i++) {
        sum += buffer[i] * buffer[i];
      }
      const rms = Math.sqrt(sum / buffer.length);
      const now = Date.now();

      if (rms > 0.02) {
        this.lastSpeech = now;
        this.hasSpeech = true;
        if (this.audio && !this.audio.paused && now - this.lastSpeech >= 200) {
          this.interruptAudio();
        }
      } else if (now - this.lastSpeech >= 700 && this.hasSpeech) {
        if (this.recorder && this.recorder.state === 'recording') {
          this.recorder.stop();
        }
      }

      this.animId = requestAnimationFrame(analyze);
    };

    this.animId = requestAnimationFrame(analyze);
  }

  // Arrêt propre du micro, ne touche pas aux promesses en cours
  async stopMic() {
    this.micEnabled = false;

    if (this.recorder && this.recorder.state === 'recording') {
      this.recorder.stop();
    }

    if (this.animId) {
      cancelAnimationFrame(this.animId);
      this.animId = null;
    }

    if (this.stream) {
      this.stream.getTracks().forEach(t => t.stop());
      this.stream = null;
    }

    if (this.ctx && this.ctx.close) {
      try { this.ctx.close(); } catch (_) {}
      this.ctx = null;
    }
  }

  // Synthèse vocale (TTS), retourne Promise résolue à la fin de la lecture
  speak(text) {
    const epoch = ++this.speechEpoch;
    if (typeof this.callbacks.onState === 'function') {
      this.callbacks.onState('thinking');
    }

    return api('/api/tts', { text }).then((blob) => {
      if (epoch !== this.speechEpoch || !blob) return;

      const url = URL.createObjectURL(blob);
      this.audio = new Audio(url);

      const cleanup = () => {
        URL.revokeObjectURL(url);
        this.audio = null;
        if (typeof this.callbacks.onState === 'function') {
          this.callbacks.onState('listening');
        }
      };

      this.audio.onended = cleanup;
      this.audio.onpause = cleanup;
      this.audio.onerror = () => {
        URL.revokeObjectURL(url);
        this.audio = null;
        if (typeof this.callbacks.onError === 'function') {
          this.callbacks.onError(new Error('Échec de lecture audio'));
        }
      };

      const playPromise = this.audio.play();

      if (typeof this.callbacks.onState === 'function') {
        this.callbacks.onState('speaking');
      }

      return playPromise.catch((err) => {
        if (typeof this.callbacks.onError === 'function') {
          this.callbacks.onError(err);
        }
        return Promise.resolve();
      });
    }).catch((err) => {
      if (typeof this.callbacks.onError === 'function') {
        this.callbacks.onError(err);
      }
      return Promise.resolve();
    });
  }

  // Interruption de l'audio en cours, n'annule pas la mission
  interruptAudio() {
    this.speechEpoch++;
    if (this.audio && !this.audio.paused) {
      this.audio.pause();
    }
  }
}

